// P58, F-SET-02: the shell's Escape closes the settings surface. The
// binding is global (no key context), so it fires regardless of what holds
// focus — including the stale focus left behind when the settings surface
// replaced the main frame. Scoped bindings (the summarizer picker menu, the
// chat composer) resolve first when their context is focused, so those keep
// consuming Escape before the shell ever sees it.
actions!(shell_settings, [CloseSettingsSurface, OpenSettingsShortcut]);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowCommand {
    NewTerminalTab,
    OpenFile,
    SaveFile,
    ToggleSidebar,
    ToggleRightPanel,
    ToggleSecondaryPane,
    RestoreLaunchSnapshot,
    NewBrowser,
    FocusAddressBar,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowCommandDisabledReason {
    NoActiveFile,
    NoActiveBrowser,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowCommandAvailability {
    Enabled,
    Disabled(WindowCommandDisabledReason),
}

fn linux_window_shortcuts() -> [(WindowCommand, &'static str); 9] {
    // #374: `ctrl-shift-s`, `ctrl-shift-i` and `ctrl-shift-o` never reach
    // the app on Windows — they are already taken there as system-wide
    // hotkeys (a `RegisterHotKey` probe for exactly those chords fails
    // while `ctrl-shift-l`/`ctrl-shift-b` succeed, and physical presses of
    // the former never arrive at the window while the latter dispatch).
    // Windows therefore slides those three one family chord over to free
    // letters that do arrive: sidebar S->D (next to S), right panel I->R
    // (Right), restore O->H (the palette row is "History: ..."). Every
    // other platform keeps the documented chords.
    let sidebar = if cfg!(target_os = "windows") {
        "ctrl-shift-d"
    } else {
        "ctrl-shift-s"
    };
    let right_panel = if cfg!(target_os = "windows") {
        "ctrl-shift-r"
    } else {
        "ctrl-shift-i"
    };
    let restore = if cfg!(target_os = "windows") {
        "ctrl-shift-h"
    } else {
        "ctrl-shift-o"
    };
    [
        (WindowCommand::NewTerminalTab, "ctrl-t"),
        (WindowCommand::OpenFile, "ctrl-o"),
        (WindowCommand::SaveFile, "ctrl-s"),
        (WindowCommand::ToggleSidebar, sidebar),
        (WindowCommand::ToggleRightPanel, right_panel),
        // #324: B is what Zed and VS Code both settled on for the secondary
        // panel, and `ctrl-shift-` is the family the two toggles above use.
        (WindowCommand::ToggleSecondaryPane, "ctrl-shift-b"),
        // F-WIN-07: Linux stand-in for macOS's `⇧⌘O` "History > Restore
        // Previous Launch" chord.
        (WindowCommand::RestoreLaunchSnapshot, restore),
        // F-WIN-06: Linux stand-in for macOS's `⇧⌘L` "New Browser" and `⌘L`
        // "Focus Address Bar" chords (App/SirioApp.swift:73-81). The port
        // draws no menu bar (see F-WIN-07 above), so both live only as
        // window-level bindings and command-palette rows.
        (WindowCommand::NewBrowser, "ctrl-shift-l"),
        (WindowCommand::FocusAddressBar, "ctrl-l"),
    ]
}

/// Display form of a window command's chord, for the command palette rows.
/// Kept beside [`linux_window_shortcuts`] (the binding source of truth) so
/// the two stay in sync — including the three #374 Windows variants — and
/// `window_shortcut_hints_match_bindings` below pins that agreement.
pub(crate) fn window_shortcut_hint(command: WindowCommand) -> &'static str {
    match command {
        WindowCommand::NewTerminalTab => "Ctrl+T",
        WindowCommand::OpenFile => "Ctrl+O",
        WindowCommand::SaveFile => "Ctrl+S",
        WindowCommand::ToggleSidebar if cfg!(target_os = "windows") => "Ctrl+Shift+D",
        WindowCommand::ToggleSidebar => "Ctrl+Shift+S",
        WindowCommand::ToggleRightPanel if cfg!(target_os = "windows") => "Ctrl+Shift+R",
        WindowCommand::ToggleRightPanel => "Ctrl+Shift+I",
        WindowCommand::ToggleSecondaryPane => "Ctrl+Shift+B",
        WindowCommand::RestoreLaunchSnapshot if cfg!(target_os = "windows") => "Ctrl+Shift+H",
        WindowCommand::RestoreLaunchSnapshot => "Ctrl+Shift+O",
        WindowCommand::NewBrowser => "Ctrl+Shift+L",
        WindowCommand::FocusAddressBar => "Ctrl+L",
    }
}

fn window_command_availability(
    command: WindowCommand,
    active_tab_kind: Option<TabKind>,
) -> WindowCommandAvailability {
    match command {
        WindowCommand::SaveFile if active_tab_kind != Some(TabKind::Editor) => {
            WindowCommandAvailability::Disabled(WindowCommandDisabledReason::NoActiveFile)
        }
        // F-WIN-06: focusing the address bar needs a browser tab to focus
        // it *in* -- unlike SaveFile there is no silent fallback target, so
        // this mirrors SaveFile's own no-active-file gate rather than
        // inventing new behavior for the case the reference app's gate
        // (`WorkspaceEngineGate`) never reaches, because this port has none.
        WindowCommand::FocusAddressBar if active_tab_kind != Some(TabKind::Browser) => {
            WindowCommandAvailability::Disabled(WindowCommandDisabledReason::NoActiveBrowser)
        }
        WindowCommand::NewTerminalTab
        | WindowCommand::OpenFile
        | WindowCommand::SaveFile
        | WindowCommand::ToggleSidebar
        | WindowCommand::ToggleRightPanel
        | WindowCommand::ToggleSecondaryPane
        | WindowCommand::RestoreLaunchSnapshot
        | WindowCommand::NewBrowser
        | WindowCommand::FocusAddressBar => WindowCommandAvailability::Enabled,
    }
}

fn bind_window_keys(cx: &mut App) {
    cx.bind_keys(
        linux_window_shortcuts()
            .into_iter()
            .map(|(command, shortcut)| match command {
                WindowCommand::NewTerminalTab => KeyBinding::new(shortcut, NewTerminalTab, None),
                WindowCommand::OpenFile => KeyBinding::new(shortcut, OpenFile, None),
                WindowCommand::SaveFile => KeyBinding::new(shortcut, SaveFile, None),
                WindowCommand::ToggleSidebar => KeyBinding::new(shortcut, ToggleSidebar, None),
                WindowCommand::ToggleRightPanel => {
                    KeyBinding::new(shortcut, ToggleRightPanel, None)
                }
                WindowCommand::ToggleSecondaryPane => {
                    KeyBinding::new(shortcut, ToggleSecondaryPane, None)
                }
                WindowCommand::RestoreLaunchSnapshot => {
                    KeyBinding::new(shortcut, RestoreLaunchSnapshot, None)
                }
                WindowCommand::NewBrowser => KeyBinding::new(shortcut, NewBrowser, None),
                WindowCommand::FocusAddressBar => KeyBinding::new(shortcut, FocusAddressBar, None),
            })
            // F-SET-02: Escape closes the settings surface. Global (no key
            // context) on purpose — it must fire even when the surface
            // replaced the previously focused element; scoped bindings
            // (composer, picker menus) resolve first when focused.
            .chain(std::iter::once(KeyBinding::new(
                "escape",
                CloseSettingsSurface,
                None,
            )))
            .chain(std::iter::once(KeyBinding::new(
                "ctrl-,",
                OpenSettingsShortcut,
                None,
            )))
            .collect::<Vec<_>>(),
    );
}

/// Whether the shell's capture-phase fallback should close a tab for this
/// keystroke. Pure so both platform arms are testable off-platform: the
/// Linux `ctrl-w` arm must yield to a focused terminal (#226), while the
/// macOS/`platform` arm is the OS close convention and never does.
fn close_tab_fallback_fires(
    key: &str,
    modifiers: Modifiers,
    is_linux: bool,
    terminal_focused: bool,
) -> bool {
    if key != "w" {
        return false;
    }
    // The close convention of the OS itself -- cmd-w on macOS, not a
    // readline key -- so it never yields to a focused terminal.
    if modifiers.platform {
        return true;
    }
    // #226: on Linux ctrl-w is readline delete-word inside a terminal, so
    // the capture-phase fallback must yield and let the `!Terminal`-scoped
    // binding decide. ctrl-shift-w is the close chord that survives inside
    // a terminal, carried by its own unscoped binding (panes.rs bind_keys);
    // this branch must not claim it.
    is_linux && modifiers.control && !modifiers.shift && !terminal_focused
}

