    #[test]
    fn every_adapter_in_the_catalog_is_a_known_registry_client() {
        // The adapter-id table inside `sirio_registry` and
        // `sirio_agents::ALL` are two lists kept in sync by hand; nothing
        // else links them, and a leaf cannot depend on the catalog. So the
        // join is pinned here, where both crates are visible: for EVERY
        // adapter, resolve with a registry carrying an agent named exactly
        // like the adapter must NOT find it via bare-name passthrough.
        // Mapped adapters look their mapped id up instead; a known-but-
        // unmapped one (omp) refuses; an adapter missing from the table
        // entirely would silently pass through and fail here.
        for adapter in sirio_agents::ALL {
            let id = adapter.id();
            let registry = sirio_registry::AcpRegistry {
                version: "1.0.0".into(),
                warnings: Vec::new(),
                agents: vec![sirio_registry::RegistryAgent {
                    id: id.to_string(),
                    name: id.to_string(),
                    version: "1.0.0".into(),
                    description: None,
                    repository: None,
                    website: None,
                    license: None,
                    icon: None,
                    distributions: vec![sirio_registry::Distribution::Npx {
                        package: format!("{id}@1.0.0"),
                        args: Vec::new(),
                    }],
                }],
            };
            let source = sirio_registry::resolve(sirio_registry::ResolveInput {
                adapter_id: id,
                builtin: adapter
                    .builtin_acp()
                    .map(|program| sirio_registry::BuiltinAcp {
                        program: program.program,
                        args: program.args,
                    }),
                builtin_on_path: false,
                installed: None,
                registry: Some(&registry),
                platform_key: "linux-x86_64",
            });
            let self_mapped = sirio_registry::registry_id(id) == Some(id);
            if self_mapped {
                // opencode maps onto its own registry row by design.
                continue;
            }
            assert_eq!(
                source,
                sirio_registry::LaunchSource::Unavailable(
                    sirio_registry::UnavailableReason::NotInRegistry
                ),
                "{id}: sirio_registry does not know this catalog adapter; \
                 it fell back to bare-name matching"
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn apple_script_string_literal_escapes_notification_text() {
        let expected = ["\"", "line", "\\n", "\\\\", "\\\"", "\""].concat();
        assert_eq!(
            apple_script_string_literal("line\n\\\""),
            expected,
            "notification content must stay inside one AppleScript string literal"
        );
        assert_eq!(apple_script_string_literal("nul\0"), "\"nul \"");
    }

    #[cfg(target_os = "windows")]
    #[test]
    fn powershell_single_quote_literal_escapes_notification_text() {
        // A single quote inside a PowerShell single-quoted string is
        // escaped by doubling it; the doubled form must survive a round
        // trip, and text without quotes passes through untouched.
        assert_eq!(
            powershell_single_quote_literal("it's broken"),
            "it''s broken",
            "an apostrophe inside the balloon text must not end the \
             PowerShell string literal"
        );
        assert_eq!(powershell_single_quote_literal("plain text"), "plain text");
        assert_eq!(powershell_single_quote_literal(""), "");
    }

