    /// The skills CLI ships as an npm shim: on Windows `npx` is `npx.cmd`,
    /// which `CreateProcess` cannot infer from the bare name — the PTY child
    /// must be handed the PATH-resolved program, the same way
    /// `agent_command_for` resolves `opencode.cmd`. Handing it the bare name
    /// is the "Install Skill does nothing" defect: the pane shows a spawn
    /// failure instead of the installer.
    #[test]
    fn skill_install_runs_the_path_resolved_program() {
        let command = sirio_project::agent_skill_install_command();
        let resolved = PathBuf::from(r"C:\Program Files\nodejs\npx.cmd");
        let shell = skill_install_shell_with(command, |program| {
            assert_eq!(program, "npx", "the bare name is what gets resolved");
            Some(resolved.clone())
        });
        let TerminalShell::WithArguments { program, args } = shell else {
            panic!("skill installation must run as a terminal command");
        };
        assert_eq!(program, resolved.to_string_lossy());
        assert_eq!(args.first().map(String::as_str), Some("skills"));
    }

    #[test]
    fn terminal_links_are_only_routed_to_their_owning_pane() {
        let event = TerminalLinkEvent {
            target: TerminalIdentity::new("pane-2", "terminal-2"),
            url: "https://example.test/pane-2".to_string(),
        };
        assert_eq!(
            terminal_link_url_for_pane(&event, "pane-2"),
            Some("https://example.test/pane-2")
        );
        assert_eq!(terminal_link_url_for_pane(&event, "pane-1"), None);
    }

    /// F-TERM-UI-02: a real `TerminalLinkEvent`, fed through the real
    /// `subscribe_terminal_link` wiring (not a reimplementation of its
    /// logic), must queue `WorkspaceAction::OpenBrowserLink` -- the same
    /// route `bind_chat`'s `ChatEvent::OpenLink` already uses to open
    /// sirio's own Browser tab -- not call out to an external browser.
    /// `terminal_links_are_only_routed_to_their_owning_pane` above already
    /// covers the pure pane-id filter; this covers the subscription that
    /// filter is wired into.
    #[gpui::test]
    fn a_terminal_link_click_queues_the_in_app_browser_tab_action(cx: &mut TestAppContext) {
        let workspace = cx.new(|cx| {
            let workspace = palette_test_workspace(cx);
            let terminal = match &workspace.tabs[0].panes {
                PaneNode::Leaf {
                    content: Some(TabContent::Terminal { view }),
                    ..
                } => view.clone(),
                _ => panic!("test tab 0 must be a terminal pane"),
            };
            terminal.update(cx, |terminal, _| {
                terminal.set_identity(TerminalIdentity::new("pane-0", "terminal-0"));
            });
            SirioWorkspace::subscribe_terminal_link(&terminal, 0, cx);
            terminal.update(cx, |_, cx| {
                cx.emit(TerminalLinkEvent {
                    target: TerminalIdentity::new("pane-0", "terminal-0"),
                    url: "https://example.test/from-terminal".to_string(),
                });
            });
            workspace
        });
        cx.run_until_parked();
        let queued_url = workspace.read_with(cx, |workspace, _| {
            let actions = workspace.pending_actions.lock().unwrap();
            actions.iter().find_map(|action| match action {
                WorkspaceAction::OpenBrowserLink(url) => Some(url.clone()),
                _ => None,
            })
        });
        assert_eq!(
            queued_url.as_deref(),
            Some("https://example.test/from-terminal"),
            "a terminal link click must queue OpenBrowserLink (the same in-app \
             Browser tab route bind_chat's ChatEvent::OpenLink uses)"
        );
    }

    /// #319: the tab context menu offers no move-between-panes entry at all,
    /// under any label. Two of them died here for different reasons —
    /// F-TAB-12 removed a permanently-disabled "Move to This Pane", and the
    /// center split removes the live "Move to Pane {id}" that replaced it —
    /// so the assertion is on the *absence of the whole family*, not on one
    /// spelling. A tab's half is derived from its `TabKind`, and no menu item
    /// can change what a tab is.
    ///
    /// The fixture puts a Secondary tab beside a Primary one, which is the
    /// state the deleted entries needed to be live in: with only one pane
    /// populated they would have been absent anyway and this would assert
    /// nothing.
    #[gpui::test]
    fn tab_context_menu_never_offers_a_move_between_panes(cx: &mut TestAppContext) {
        let workspace = cx.new(|cx| {
            let mut workspace = palette_test_workspace_with_tab_count(cx, 2);
            workspace.tabs[1].kind = sirio_project::TabKind::Editor;
            workspace.rebuild_center_split();
            workspace.tab_menu_tab = Some(0);
            workspace
        });

        let items = workspace.read_with(cx, |workspace, _| workspace.tab_context_items());

        let offender = items
            .iter()
            .find(|item| item.label().contains("Pane") || item.label().contains("pane"));
        assert!(
            offender.is_none(),
            "no context item may name a pane destination, found {:?}",
            offender.map(|item| item.label())
        );

        // The reordering entries that sat beside it must survive, so this
        // fails on a re-addition rather than on the menu going empty.
        assert!(
            items.iter().any(|item| item.label() == "Move Earlier"),
            "reordering within a pane is still offered"
        );
    }

    /// A manifest artifact payload that never touches the network: the URL
    /// is under `.invalid`, and `sirio_update` verifies hash/signature only
    /// after a real fetch, so a check outcome built from it is inert.
    fn test_manifest_artifact() -> sirio_release::ManifestArtifact {
        sirio_release::ManifestArtifact {
            url: "https://example.invalid/sirio-0.7.0".into(),
            sha256: "00".repeat(32),
            signature: "A".repeat(88),
        }
    }

    /// A minimal attached workspace for the host-update tests. The
    /// compiled channel is Dev on a test build, so `attach_update_host`
    /// seeds the live state and returns without spawning the poll or drain
    /// tasks — outcomes are driven by hand, deterministically.
    fn update_host_test_fixture(cx: &mut Context<SirioWorkspace>) -> SirioWorkspace {
        let unique = TEST_WORKSPACE_ID.fetch_add(1, AtomicOrdering::Relaxed);
        let scratch_root = std::env::temp_dir()
            .canonicalize()
            .expect("canonicalize temp dir")
            .join(format!("sirio-update-host-{}-{unique}", std::process::id()));
        let working_directory = scratch_root.join("worktree");
        std::fs::create_dir_all(&working_directory).expect("create update host worktree");
        let project_catalog = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "update-project".into(),
            name: "Update Project".into(),
            root_path: working_directory.clone(),
            is_git: true,
            worktrees: vec![session::CatalogWorktree {
                branch: "main".into(),
                path: working_directory.clone(),
                is_primary: true,
            }],
        }]);
        let pending_actions = Arc::new(Mutex::new(Vec::new()));
        let control_actions = Arc::new(Mutex::new(Vec::new()));
        let panes = Arc::new(PaneRegistry::new());
        let state = Arc::new(Mutex::new(ControlState::from_catalog(
            &project_catalog,
            &working_directory,
        )));
        let session_path = scratch_root.join("sirio.sqlite");
        let session = SessionStore::open(&session_path);
        let titlebar = cx.new(Titlebar::new);
        let sidebar = cx.new(|cx| Sidebar::from_projects(sidebar_projects(&project_catalog), cx));
        let tab_bar = cx.new(|cx| TabBar::new(cx));
        let status_bar = cx.new(|_| {
            StatusBar::new(UsageBarData {
                branch: "main".into(),
                path: working_directory.to_string_lossy().into_owned(),
            })
        });
        let settings = cx.new(|cx| Settings::new(cx));
        let right_panel = cx.new(|_| RightPanel::new(working_directory.clone()));
        let mut workspace = SirioWorkspace::new(
            titlebar,
            sidebar,
            tab_bar,
            status_bar,
            settings,
            right_panel,
            panes,
            state,
            Vec::new(),
            0,
            working_directory.clone(),
            pending_actions.clone(),
            pending_actions,
            control_actions,
            session,
            project_catalog,
            "Update Project/main".into(),
            RestoredSession {
                working_directory,
                tabs: Vec::new(),
                tab_states: Vec::new(),
                diagnostics: Vec::new(),
            },
            AgentActivityModel::new(),
            None,
            None,
            None,
            false,
            325.0,
            405.0,
            500,
            cx,
        );
        let updater = Arc::new(Mutex::new(sirio_update::Updater::new(
            scratch_root.join("updates"),
            sirio_release::AcceptedKeys::from_base64(std::iter::empty::<&str>())
                .expect("empty key set parses"),
        )));
        let enabled = Arc::new(AtomicBool::new(true));
        let outcomes = Arc::new(Mutex::new(None::<UpdateHostOutcome>));
        let wake = Arc::new(AtomicBool::new(false));
        workspace.attach_update_host(
            UiUpdateState {
                enabled: true,
                channel: "dev".into(),
                status: UiUpdateStatus::NotDue,
                last_checked: None,
            },
            updater.clone(),
            enabled.clone(),
            outcomes.clone(),
            wake.clone(),
            cx,
        );
        workspace
    }

