    /// Pulls the fixture's one live `TerminalView` back out of a workspace
    /// built by `worktree_urgency_test_workspace` -- needed to focus it
    /// directly and to read its real PTY-backed screen content afterward.
    fn urgency_fixture_terminal(
        workspace: &Entity<SirioWorkspace>,
        cx: &VisualTestContext,
    ) -> Entity<TerminalView> {
        workspace.read_with(&cx.cx, |workspace, _| {
            let mut view = None;
            workspace.tabs[0].panes.for_each(&mut |_, content| {
                if let TabContent::Terminal { view: v } = content {
                    view = Some(v.clone());
                }
            });
            view.expect("the urgency fixture's sole tab has a terminal pane")
        })
    }

    /// Positive control for
    /// `pane_close_confirm_banner_blocks_keystrokes_from_reaching_the_focused_terminal`
    /// below: with no dialog ever opened, real keystrokes sent to a
    /// genuinely focused terminal reach its PTY and come back echoed onto
    /// the screen. Proves the leak detector that test relies on can detect
    /// a leak at all -- a detector that never fires proves nothing (a
    /// refuted earlier verdict on this exact banner passed for exactly that
    /// reason: it drove the mouse-only right-click path, which never put
    /// keyboard focus on the terminal, so its own "no leak" check could not
    /// have failed either way).
    #[gpui::test]
    async fn terminal_keystrokes_reach_the_pty_when_no_dialog_is_open(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let (root, _worktrees) = urgency_test_root("control-no-dialog");
        let root_for_window = root.clone();
        let window =
            cx.add_window(|_window, cx| worktree_urgency_test_workspace(cx, &root_for_window));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });
        let terminal = urgency_fixture_terminal(&workspace, &cx);

        cx.update(|window, app| {
            let focus = terminal.read(app).focus_handle(app);
            focus.focus(window, app);
        });
        cx.run_until_parked();

        let needle = format!("CONTROL_ECHO_{}", std::process::id());
        cx.simulate_input(&needle);

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(5));
            cx.run_until_parked();
            let seen = terminal.read_with(&cx.cx, |terminal, _| {
                String::from_utf8_lossy(&terminal.snapshot().scrollback).contains(&needle)
            });
            if seen {
                break;
            }
            if std::time::Instant::now() >= deadline {
                panic!(
                    "control failed: typed input never reached the focused terminal's PTY \
                     (the leak-detection test below cannot be trusted if this control cannot \
                     pass)"
                );
            }
            std::thread::sleep(Duration::from_millis(10));
        }

        shutdown_workspace_terminals(&workspace, &mut cx);
        let _ = std::fs::remove_dir_all(&root);
    }

    /// The refutation this closes (`docs/linux-rewrite/tasks/
    /// P103-two-close-confirmation-contracts.md`): `render_pane_close_confirm`
    /// used to draw the "Close terminal?" banner as a plain
    /// absolutely-positioned div with no `.track_focus()`/`window.focus()`
    /// and no case in `handle_root_key_down`, so it never took keyboard
    /// focus. Opened while a terminal held focus -- the ordinary case for
    /// the real `ctrl-alt-w` chord a person presses -- every keystroke,
    /// Enter included, went straight into the live PTY underneath.
    ///
    /// Driven from the path where the failure is possible, which is the
    /// specific thing the refuted earlier verdict got wrong: types into the
    /// terminal *first* so it genuinely holds focus, opens the banner with
    /// the real `ctrl-alt-w` chord (not a mouse click), types more text plus
    /// Escape while it is up, and only then checks the PTY. Escape must
    /// cancel (not close), and the leak needle must never appear -- checked
    /// against the same fully-settled snapshot the positive control above
    /// proved its own canary reaches, so an absent needle here cannot be
    /// explained by "didn't wait long enough".
    #[gpui::test]
    async fn pane_close_confirm_banner_blocks_keystrokes_from_reaching_the_focused_terminal(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let (root, _worktrees) = urgency_test_root("leak-ctrl-alt-w");
        let root_for_window = root.clone();
        let window =
            cx.add_window(|_window, cx| worktree_urgency_test_workspace(cx, &root_for_window));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });
        let terminal = urgency_fixture_terminal(&workspace, &cx);

        // Type into the terminal *first*, proving it genuinely holds focus
        // before the banner ever opens -- the exact precondition the
        // refuted verdict's mouse-driven check never reached.
        cx.update(|window, app| {
            let focus = terminal.read(app).focus_handle(app);
            focus.focus(window, app);
        });
        cx.run_until_parked();
        let preamble = format!("PREAMBLE_{}", std::process::id());
        cx.simulate_input(&preamble);
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(5));
            cx.run_until_parked();
            let seen = terminal.read_with(&cx.cx, |terminal, _| {
                String::from_utf8_lossy(&terminal.snapshot().scrollback).contains(&preamble)
            });
            if seen {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "setup failed: the terminal never echoed the preamble, so it was never really focused"
            );
            std::thread::sleep(Duration::from_millis(10));
        }

        // The real chord a person presses -- not a mouse click on a context
        // menu item, which is the path the refuted verdict's own check used
        // and which never puts keyboard focus on the terminal at all.
        cx.simulate_keystrokes("ctrl-alt-w");
        cx.run_until_parked();
        assert!(
            cx.debug_bounds("pane-close-confirm").is_some(),
            "ctrl-alt-w must open the close-confirm banner"
        );

        let leak_needle = format!("LEAK_{}", std::process::id());
        cx.simulate_input(&leak_needle);
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();

        assert!(
            cx.debug_bounds("pane-close-confirm").is_none(),
            "Escape must cancel the banner"
        );
        assert_eq!(
            workspace.read_with(&cx.cx, |workspace, _| workspace.tabs.len()),
            1,
            "Escape must cancel the close, not confirm it -- the tab must survive"
        );

        // Cancelling restores real keyboard focus to the terminal (see
        // `cancel_pending_pane_close`) -- type a canary and wait for *it*,
        // rather than sleeping a fixed duration, so the absence check below
        // cannot be explained by "the test didn't wait long enough": by the
        // time the canary (typed strictly after the leak needle) has been
        // echoed back, anything typed earlier that reached the PTY would
        // already be in the same buffer.
        let canary = format!("CANARY_{}", std::process::id());
        cx.simulate_input(&canary);
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(5));
            cx.run_until_parked();
            let seen = terminal.read_with(&cx.cx, |terminal, _| {
                String::from_utf8_lossy(&terminal.snapshot().scrollback).contains(&canary)
            });
            if seen {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "cancelling the banner never restored terminal focus -- the canary never echoed"
            );
            std::thread::sleep(Duration::from_millis(10));
        }

        let final_screen = terminal.read_with(&cx.cx, |terminal, _| {
            String::from_utf8_lossy(&terminal.snapshot().scrollback).into_owned()
        });
        assert!(
            !final_screen.contains(&leak_needle),
            "keystrokes typed while the close-confirm banner was open must not reach the PTY"
        );

        shutdown_workspace_terminals(&workspace, &mut cx);
        let _ = std::fs::remove_dir_all(&root);
    }

    fn activity_status(
        workspace: &Entity<SirioWorkspace>,
        cx: &VisualTestContext,
    ) -> Option<AgentStatus> {
        workspace.read_with(&cx.cx, |workspace, _| workspace.activity.status("pane-0"))
    }

    /// A view holding nothing but the chat's thinking orb, counting its own
    /// renders so a test can tell whether the shared clock is driving it.
    struct ThinkingOrbFixture {
        renders: usize,
    }

    impl Render for ThinkingOrbFixture {
        fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            self.renders += 1;
            let theme = Theme::light();
            div().child(sirio_ui::loading::thinking_indicator(
                "thinking-orb-fixture",
                &theme,
                window,
                cx,
            ))
        }
    }

    /// The thinking orb is watched from another window while an agent works.
    /// bezel's clock refuses to drive a window that is not active, but that
    /// does not freeze the orb: the chat re-renders on every ACP chunk whether
    /// or not the window is active, and each render samples the orb's live
    /// phase — so the orb jumps from chunk to chunk instead of turning. The
    /// app therefore keeps the drive on: an inactive window's orb is still
    /// owed its frames.
    #[gpui::test]
    async fn the_thinking_orb_keeps_turning_while_the_window_is_inactive(cx: &mut TestAppContext) {
        cx.update(init_motion);
        let (fixture, cx) = cx.add_window_view(|_, _| ThinkingOrbFixture { renders: 0 });
        cx.deactivate_window();
        // One render on the inactive window, as an ACP chunk provokes.
        fixture.update(&mut cx.cx, |_, cx| cx.notify());
        cx.run_until_parked();
        let before = fixture.read_with(&cx.cx, |fixture, _| fixture.renders);
        // Half a second of clock, at the 30 fps the orb claims.
        for _ in 0..15 {
            cx.background_executor
                .advance_clock(Duration::from_millis(33));
            cx.run_until_parked();
        }
        let after = fixture.read_with(&cx.cx, |fixture, _| fixture.renders);
        assert!(
            after >= before + 10,
            "an inactive window's orb must keep being driven: {before} -> {after} renders"
        );
    }

    /// A running agent mounts the sidebar's spinner, whose lease re-renders
    /// the sidebar at 30 fps. Every child view of the shell is cached, so
    /// those frames must replay the still terminal pane rather than render
    /// it: the shell frame count moves, the terminal's render count does not.
    #[gpui::test]
    async fn a_spinner_frame_replays_the_still_terminal_pane(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory =
            std::env::temp_dir().join(format!("sirio-cached-pane-frames-{}", std::process::id()));
        std::fs::create_dir_all(&working_directory).expect("create cached-pane test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn cached-pane test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        workspace.update(&mut cx.cx, |workspace, cx| {
            // Tests mount child views uncached by default (see the field's
            // doc); this is the one test that needs the app's behaviour.
            workspace.cache_child_views = true;
            workspace
                .activity
                .agent_spawned("pane-0", "claude", Instant::now());
            workspace.mark_activity_dirty();
            cx.notify();
        });
        // The spinner's lease refuses to claim frames while no window is
        // active (`pause_when_inactive`), and a test window is never active
        // unless activated.
        cx.update(|window, _| window.activate_window());
        let tick = |cx: &mut VisualTestContext| {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(40));
            cx.run_until_parked();
        };
        // Let the spawn, the debounced resize and the first spinner frames
        // settle so the counts below describe a genuinely still pane.
        for _ in 0..10 {
            tick(cx);
        }
        let terminal_renders_before =
            terminal.read_with(&cx.cx, |terminal, _| terminal.render_count());
        let frames_before = workspace.read_with(&cx.cx, |workspace, _| workspace.frames_rendered);

        for _ in 0..10 {
            tick(cx);
        }
        let frames = workspace.read_with(&cx.cx, |workspace, _| workspace.frames_rendered);
        assert!(
            frames >= frames_before + 5,
            "the spinner lease must keep the shell drawing ({frames_before} -> {frames})"
        );
        assert_eq!(
            terminal.read_with(&cx.cx, |terminal, _| terminal.render_count()),
            terminal_renders_before,
            "a still cached pane must be replayed, not re-rendered, by spinner frames"
        );

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// With every sidebar row its own cached view, the spinner lease of a
    /// running worktree must re-render that row alone: the project row (and
    /// any other row) is replayed while the running row keeps animating.
    #[gpui::test]
    async fn a_spinner_frame_replays_the_other_sidebar_rows(cx: &mut TestAppContext) {
        use sirio_ui::sidebar::RowKind;

        cx.set_global(Theme::light());
        let working_directory =
            std::env::temp_dir().join(format!("sirio-cached-rows-frames-{}", std::process::id()));
        std::fs::create_dir_all(&working_directory).expect("create cached-rows test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn cached-rows test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.cache_child_views = true;
            workspace
                .sidebar
                .update(cx, |sidebar, _| sidebar.set_cache_rows(true));
            workspace
                .activity
                .agent_spawned("pane-0", "claude", Instant::now());
            workspace.mark_activity_dirty();
            cx.notify();
        });
        cx.update(|window, _| window.activate_window());
        let tick = |cx: &mut VisualTestContext| {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(40));
            cx.run_until_parked();
        };
        for _ in 0..10 {
            tick(cx);
        }
        let counts = |cx: &VisualTestContext| {
            workspace.read_with(&cx.cx, |workspace, app| {
                workspace.sidebar.read(app).row_render_counts(app)
            })
        };
        let before = counts(cx);
        assert!(
            before.iter().any(|(_, kind, _)| *kind == RowKind::Worktree)
                && before.iter().any(|(_, kind, _)| *kind == RowKind::Project),
            "the fixture draws a project row and a worktree row: {before:?}"
        );

        for _ in 0..10 {
            tick(cx);
        }
        let after = counts(cx);
        for ((id, kind, was), (_, _, now)) in before.iter().zip(after.iter()) {
            match kind {
                RowKind::Worktree => assert!(
                    *now >= was + 5,
                    "the running worktree row {id} must keep rendering with its spinner ({was} -> {now})"
                ),
                _ => assert_eq!(
                    now, was,
                    "row {id} ({kind:?}) must be replayed, not re-rendered, by spinner frames"
                ),
            }
        }

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// Closing a tab must forget its panes in the activity model: the model
    /// is keyed by pane id and the next pane to get that id would otherwise
    /// inherit the closed pane's status, agent and ownership.
    #[gpui::test]
    async fn closing_a_tab_forgets_its_pane_in_the_activity_model(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory =
            std::env::temp_dir().join(format!("sirio-close-tab-activity-{}", std::process::id()));
        std::fs::create_dir_all(&working_directory).expect("create close-tab test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn close-tab test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        cx.run_until_parked();

        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace
                .activity
                .agent_spawned("pane-0", "claude", Instant::now());
            workspace.mark_activity_dirty();
            workspace.sync_activity(cx);
        });
        assert_eq!(activity_status(&workspace, &cx), Some(AgentStatus::Running));

        // `close_tab` arms the reconcile itself; the explicit one below only
        // makes the assertion independent of whether a frame ran in between.
        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.close_tab(0, None, cx);
            workspace.mark_activity_dirty();
            workspace.sync_activity(cx);
        });
        assert_eq!(activity_status(&workspace, &cx), None);
        assert!(workspace.read_with(&cx.cx, |workspace, _| {
            workspace.activity.agent_id("pane-0").is_none()
                && !workspace.activity.is_process_owned("pane-0")
                && !workspace.activity.is_title_owned("pane-0")
        }));

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// The control registry must publish a live source during the render
    /// refresh without asking the terminal owner thread for its scrollback.
    /// An explicit registry read is the only operation in this test allowed
    /// to cross that boundary.
    #[gpui::test]
    async fn render_never_captures_scrollback(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory = std::env::temp_dir().join(format!(
            "sirio-render-no-scrollback-capture-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&working_directory).expect("create regression test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn regression test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        cx.run_until_parked();

        let panes = workspace.read_with(&cx.cx, |workspace, _| workspace.panes.clone());
        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.sync_control_panes(cx);
        });
        let before = sirio_terminal::SCROLLBACK_CAPTURES.load(AtomicOrdering::SeqCst);
        for _ in 0..3 {
            workspace.update(&mut cx.cx, |workspace, cx| {
                workspace.mark_activity_dirty();
                workspace.sync_activity(cx);
                cx.notify();
            });
            cx.run_until_parked();
        }
        assert_eq!(
            sirio_terminal::SCROLLBACK_CAPTURES.load(AtomicOrdering::SeqCst),
            before,
            "render and activity synchronization must never capture scrollback"
        );

        panes.read("pane-0").expect("published terminal pane");
        assert!(
            sirio_terminal::SCROLLBACK_CAPTURES.load(AtomicOrdering::SeqCst) > before,
            "an explicit registry read must consult the live scrollback source"
        );

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// Activity reconciliation is armed by changed evidence or an explicit
    /// activity mutation, then consumed at most once by the next render.
    /// Repainting an unchanged workspace must not repeat the full reconcile.
    #[gpui::test]
    async fn render_reconciles_only_when_evidence_changed(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory = std::env::temp_dir().join(format!(
            "sirio-render-activity-reconcile-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&working_directory).expect("create reconcile test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn reconcile test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        cx.run_until_parked();

        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.mark_activity_dirty();
            workspace.sync_activity(cx);
        });
        cx.run_until_parked();
        let reconciles = workspace.read_with(&cx.cx, |workspace, _| workspace.reconciles);

        for _ in 0..3 {
            workspace.update(&mut cx.cx, |_, cx| cx.notify());
            cx.run_until_parked();
        }
        assert_eq!(
            workspace.read_with(&cx.cx, |workspace, _| workspace.reconciles),
            reconciles,
            "an unchanged workspace must not reconcile merely because it rendered"
        );

        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.mark_activity_dirty();
            cx.notify();
        });
        cx.run_until_parked();
        assert_eq!(
            workspace.read_with(&cx.cx, |workspace, _| workspace.reconciles),
            reconciles + 1,
            "arming activity must make the next render reconcile"
        );

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// Layer C's content scan now runs on the background executor
    /// (`SirioWorkspace::spawn_content_signal_scan`) instead of inline in
    /// `subscribe_terminal_activity`'s synchronous callback. Drives a real
    /// PTY through the same OSC-title-then-settled-content sequence as
    /// `panes::tests::real_pty_activity_status_follows_osc_title_then_settled_content`,
    /// but through the app's real subscription rather than a test-local
    /// bypass, so a broken UI-thread/background hand-off would leave the
    /// settled content signal never applied.
    #[gpui::test]
    async fn workspace_wires_real_settled_content_into_activity_model(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory = std::env::temp_dir().join(format!(
            "sirio-activity-content-wiring-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&working_directory)
            .expect("create content activity test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec![
                "-c".into(),
                "sleep 0.1; printf '\\033]0;. working\\007'; sleep 0.2; printf 'Do you want to proceed?\\n'; exec sleep 1"
                    .into(),
            ],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn content activity test terminal")
        });
        let workspace = cx.update(|_, app| {
            app.new(|cx| activity_test_workspace(terminal.clone(), working_directory.clone(), cx))
        });

        let deadline = std::time::Instant::now() + Duration::from_secs(30);
        while std::time::Instant::now() < deadline {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(5));
            cx.run_until_parked();
            if activity_status(&workspace, &cx) == Some(AgentStatus::NeedsInput) {
                terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
                cx.run_until_parked();
                return;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        panic!(
            "the app-level terminal subscription never applied the background-scanned \
             content signal; status was {:?}",
            activity_status(&workspace, &cx)
        );
    }

    /// Rendering a terminal with the same sole-tab membership must not notify
    /// the terminal entity; a real membership change remains observable.
    #[gpui::test]
    async fn render_leaves_an_unchanged_terminal_unnotified(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory = std::env::temp_dir().join(format!(
            "sirio-render-terminal-notify-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&working_directory).expect("create terminal notify test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exec sleep 60".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn terminal notify test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        cx.run_until_parked();

        let fires = Rc::new(Cell::new(0));
        let observed_fires = fires.clone();
        let _subscription = cx.update(|_, app| {
            app.observe(&terminal, move |_, _| {
                observed_fires.set(observed_fires.get() + 1);
            })
        });

        for _ in 0..3 {
            workspace.update(&mut cx.cx, |_, cx| cx.notify());
            cx.run_until_parked();
        }
        assert_eq!(
            fires.get(),
            0,
            "rendering an unchanged terminal must not notify its entity"
        );

        let sole_tab_in_group = terminal.read_with(&cx.cx, |terminal, _| {
            terminal.sole_tab_in_group()
        });
        terminal.update(&mut cx.cx, |terminal, cx| {
            assert!(terminal.set_sole_tab_in_group(!sole_tab_in_group));
            cx.notify();
        });
        cx.run_until_parked();
        assert!(
            fires.get() > 0,
            "a real sole-tab membership change must notify the terminal entity"
        );

        terminal.update(&mut cx.cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
        let _ = std::fs::remove_dir_all(working_directory);
    }

