    /// F-CORE-WSP-01: `TabKind`'s five variants are the port's real,
    /// live content-kind taxonomy (the successor to the dead
    /// `LegacyWorkspaceTab.ContentKind`), and `AgentActivityModel` is the
    /// real activity layer -- but the row's specific per-kind identity
    /// claim ("terminal activity exposes leaf pane IDs and chat exposes
    /// its tab ID, while documents expose no activity pane") had never
    /// been drawn side by side in one frame. This does: one tab of each
    /// of the three kinds the clause actually distinguishes, with
    /// activity registered identically under every one of their pane
    /// ids -- the document tab's registration is adversarial, proving
    /// `tab_status`'s exclusion is the real `TabContent::File { .. } =>
    /// return` match arm and not a lucky absence of data under that key.
    #[gpui::test]
    async fn drawn_tab_status_distinguishes_split_terminal_chat_and_document(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let working_directory =
            std::env::temp_dir().join(format!("sirio-wsp01-kinds-{}", std::process::id()));
        std::fs::create_dir_all(&working_directory).expect("create wsp01 test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "sleep 30".into()],
        };
        let (terminal_a, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx).expect("spawn terminal leaf a")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal_a.clone(), working_directory.clone(), cx)
        });

        let file_path = working_directory.join("note.md");
        std::fs::write(&file_path, b"hello").expect("write wsp01 test file");

        workspace.update(cx, |workspace, cx| {
            // Split the existing Terminal tab (id 0, sole leaf pane 0) into
            // two leaves -- pane 0 stays unregistered (idle), pane 1 gets a
            // registered agent, so the tab's *worst* status must surface.
            let terminal_b = cx.new(|cx| {
                TerminalView::with_shell(&working_directory, TerminalShell::System, cx)
                    .expect("spawn terminal leaf b")
            });
            let split = workspace.tabs[0].panes.split_focused(
                0,
                1,
                SplitDirection::Horizontal,
                TabContent::Terminal { view: terminal_b },
            );
            assert!(split, "the terminal tab must accept a second leaf");
            workspace
                .activity
                .agent_spawned("pane-1", "codex", Instant::now());

            // A Chat tab: a real ACP Chat entity (deliberately pointed at a
            // missing binary -- the same tolerated-failure pattern
            // `drawn_chat_transcript_gets_the_full_center_surface_height`
            // already uses) with its own registered pane id.
            let chat = cx.new(|cx| {
                Chat::launch_with_command(
                    AgentCommand::new("/definitely/missing/sirio-acp-agent"),
                    working_directory.clone(),
                    cx,
                )
            });
            workspace.tabs.push(OpenTab {
                id: 1,
                persistence_id: "wsp01-chat".into(),
                title: "Chat".into(),
                kind: TabKind::AgentChat,
                agent_icon: None,
                agent_id: Some("codex".into()),
                session_state: SessionTabState::with_root(2),
                panes: PaneNode::leaf(2, TabContent::Chat(chat)),
                focused_pane: 2,
                title_is_auto_named: true,
            });
            workspace
                .activity
                .agent_spawned("pane-2", "codex", Instant::now());

            // A document tab -- and the adversarial part: register activity
            // under this pane's own id too. If `tab_status`'s File
            // exclusion were ever accidental (an id that just never
            // collided) rather than the real match-arm exclusion, this
            // would flip the assertion below from absent to present.
            let view = cx.new(|cx| FileView::new(file_path.clone(), cx));
            workspace.tabs.push(OpenTab {
                id: 2,
                persistence_id: "wsp01-doc".into(),
                title: "note.md".into(),
                kind: TabKind::Editor,
                agent_icon: None,
                agent_id: None,
                session_state: SessionTabState::with_root(3),
                panes: PaneNode::leaf(3, TabContent::File { view }),
                focused_pane: 3,
                title_is_auto_named: true,
            });
            workspace
                .activity
                .agent_spawned("pane-3", "codex", Instant::now());

            // #323: a tab pushed by hand never went through `add_file_tab`,
            // so nothing opened the pane it is drawn in.
            workspace.open_secondary_pane();
            workspace.rebuild_center_split();
            cx.notify();
        });
        cx.run_until_parked();

        // Terminal tab (split, one leaf idle + one leaf running): the worst
        // status across leaf pane ids wins.
        assert!(
            cx.debug_bounds("workspace-tab-status-running-0").is_some(),
            "a split terminal tab must surface its worst leaf's status"
        );
        // Chat tab: its own registered pane id drives the glyph.
        assert!(
            cx.debug_bounds("workspace-tab-status-running-1").is_some(),
            "a chat tab must surface its own registered activity"
        );
        // Document tab: no glyph at all, despite activity registered under
        // its own pane id above -- proves the exclusion is real, not luck.
        assert!(
            cx.debug_bounds("workspace-tab-status-running-2").is_none(),
            "a document tab must never surface activity, even when data exists under its pane id"
        );
        assert!(
            cx.debug_bounds("workspace-tab-status-idle-2").is_none(),
            "a document tab draws no status glyph at all, not even idle"
        );
        assert!(
            cx.debug_bounds("workspace-tab-status-2").is_some(),
            "the tab-status wrapper itself is always drawn"
        );

        let doc_status = workspace.read_with(&cx.cx, |workspace, app| {
            workspace.tab_status(&workspace.tabs[2], app)
        });
        assert_eq!(
            doc_status, None,
            "tab_status must return None for an all-File-pane tab, not Some(Idle)"
        );

        terminal_a.update(cx, |terminal, _| terminal.shutdown());
        cx.run_until_parked();
    }

    /// P117: a completed chat turn returns a full transcript over the control socket and draws
    /// nothing on screen. The frame shows the composer at the *top* of the pane with ~670 px of
    /// empty below it, which is the layout a `flex_col` produces when its first child measured
    /// zero. This pins the geometry so the defect cannot come back silently.
    ///
    /// This is a test, not the proof — see `docs/linux-rewrite/P117-report.md` for the frame.
    #[gpui::test]
    async fn drawn_chat_transcript_gets_the_full_center_surface_height(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let window = cx.add_window(|_window, cx| {
            let mut workspace = palette_test_workspace(cx);
            let chat = cx.new(|cx| {
                Chat::launch_with_command(
                    AgentCommand::new("/definitely/missing/sirio-acp-agent"),
                    std::env::temp_dir(),
                    cx,
                )
            });
            workspace.tabs[0] = OpenTab {
                id: 0,
                persistence_id: "test-chat".into(),
                title: "Chat".into(),
                kind: TabKind::AgentChat,
                agent_icon: Some(Icon::Codex),
                agent_id: Some("codex".into()),
                session_state: SessionTabState::with_root(0),
                panes: PaneNode::leaf(0, TabContent::Chat(chat)),
                focused_pane: 0,
                title_is_auto_named: true,
            };
            workspace.rebuild_center_split();
            workspace
        });
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();

        let centre = cx
            .debug_bounds("centre-surface")
            .expect("the centre surface wrapper is mounted");
        let root = cx
            .debug_bounds("chat-root")
            .expect("the chat root is mounted");
        let transcript = cx
            .debug_bounds("chat-transcript")
            .expect("the chat transcript is mounted");
        assert!(
            transcript.size.height > px(200.0),
            "the mounted chat transcript must receive the center surface height; \
             centre-surface={:?} group-surfaces-wrapper={:?} pane-group-surface={:?} \
             pane-leaf={:?} pane-surface={:?} chat-root={:?} chat-transcript={:?}",
            centre.size,
            cx.debug_bounds("group-surfaces-wrapper").map(|b| b.size),
            cx.debug_bounds("pane-group-surface").map(|b| b.size),
            cx.debug_bounds("pane-leaf").map(|b| b.size),
            cx.debug_bounds("pane-surface").map(|b| b.size),
            root.size,
            transcript.size
        );
    }

    /// F-CHAT diagnostic (chat surface renders empty): the same geometry
    /// invariant as the sibling test above, but for a chat tab built by
    /// `restore_tabs` -- the constructor `select_worktree` and app-startup
    /// both use -- instead of a direct `workspace.tabs[0] = OpenTab { .. }`
    /// assignment. The two construction paths are not equivalent: a
    /// restore-built chat tab's composer was found pushed off the bottom of
    /// the pane (the transcript's `flex_1` grows to consume the whole
    /// height), even though every field on the `Chat` entity itself is
    /// identical to the working, directly-constructed case.
    #[gpui::test]
    async fn drawn_restored_chat_composer_stays_within_the_center_surface(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        // A chat tab is restored only when its launch source resolves; seed
        // one for this fixture before the workspace (and its store root)
        // are constructed.
        let agents_root = std::env::temp_dir().join(format!(
            "sirio-drawn-composer-agents-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&agents_root);
        seed_codex_acp_manifest(&agents_root);
        *TEST_AGENTS_ROOT.write().unwrap() = Some(agents_root);
        let window = cx.add_window(|window, cx| {
            let mut workspace = palette_test_workspace(cx);
            let restored = RestoredSession {
                working_directory: workspace.working_directory.clone(),
                tabs: vec![SessionTab {
                    id: "test-restored-chat".into(),
                    title: "Chat".into(),
                    kind: "chat".into(),
                    agent_id: Some(AgentRef::adapter("codex")),
                    active: true,
                }],
                tab_states: vec![SessionTabState::default()],
                diagnostics: Vec::new(),
            };
            let mut activity_model = AgentActivityModel::new();
            let (tabs, active) = restore_tabs(
                &restored,
                &workspace.working_directory.clone(),
                Some(window),
                &mut activity_model,
                &BTreeMap::new(),
                cx,
            );
            workspace.tabs = tabs;
            workspace.active_tab = active;
            workspace.activity = activity_model;
            workspace.rebuild_center_split();
            workspace
        });
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();

        let centre = cx
            .debug_bounds("centre-surface")
            .expect("the centre surface wrapper is mounted");
        let root = cx
            .debug_bounds("chat-root")
            .expect("the chat root is mounted");
        let composer = cx
            .debug_bounds("composer")
            .expect("the composer is mounted");
        let centre_bottom = centre.origin.y + centre.size.height;
        let composer_bottom = composer.origin.y + composer.size.height;
        assert!(
            composer_bottom <= centre_bottom + px(1.0),
            "the restored chat's composer must stay within the visible center surface, \
             not be pushed off the bottom by an oversized transcript; \
             centre-surface={:?} chat-root={:?} composer={:?}",
            centre,
            root.size,
            composer,
        );
    }

    #[gpui::test]
    async fn restored_legacy_chat_does_not_inherit_sibling_pane_activity(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            let mut workspace = palette_test_workspace_with_tab_count(cx, 0);
            let restored_tab = |id: &str, title: &str, active: bool| SessionTab {
                id: id.into(),
                title: title.into(),
                kind: "chat".into(),
                agent_id: None,
                active,
            };
            let restored = RestoredSession {
                working_directory: workspace.working_directory.clone(),
                tabs: vec![
                    restored_tab("first-chat", "First chat", false),
                    restored_tab("second-chat", "Second chat", false),
                    restored_tab("sibling-chat", "Sibling chat", false),
                    restored_tab("legacy-chat", "Chat", false),
                    restored_tab("active-chat", "Active chat", true),
                ],
                tab_states: vec![
                    SessionTabState::default(),
                    SessionTabState::with_root(2),
                    SessionTabState::with_root(3),
                    SessionTabState::default(),
                    SessionTabState::with_root(4),
                ],
                diagnostics: Vec::new(),
            };
            let mut activity = AgentActivityModel::new();
            let (tabs, active) = restore_tabs(
                &restored,
                &workspace.working_directory.clone(),
                None,
                &mut activity,
                &BTreeMap::new(),
                cx,
            );
            workspace.tabs = tabs;
            workspace.active_tab = active;
            workspace.activity = activity;
            workspace.rebuild_center_split();
            workspace
        });

        workspace.update(cx, |workspace, cx| {
            workspace
                .activity
                .notify("pane-3", AgentStatus::Running, Instant::now());
            workspace.sync_entity_evidence(cx);

            let legacy_index = workspace
                .tabs
                .iter()
                .position(|tab| tab.persistence_id == "legacy-chat")
                .expect("restored legacy chat");
            let mut legacy_pane = None;
            workspace.tabs[legacy_index]
                .panes
                .for_each(&mut |pane_id, _| legacy_pane = Some(pane_id));
            let mut pane_ids = Vec::new();
            for tab in &workspace.tabs {
                tab.panes
                    .for_each(&mut |pane_id, _| pane_ids.push(pane_id));
            }
            let distinct_pane_ids = pane_ids.iter().copied().collect::<HashSet<_>>();
            assert_eq!(
                pane_ids.len(),
                distinct_pane_ids.len(),
                "restored tabs must not share a pane id"
            );
            assert_ne!(
                legacy_pane,
                Some(3),
                "a missing legacy root must avoid the persisted sibling pane id"
            );
            assert_eq!(
                workspace.tab_status(&workspace.tabs[legacy_index], cx),
                Some(ActivityStatus::Idle),
                "the legacy tab must not render a sibling pane's Running status"
            );
        });
    }

    #[gpui::test]
    async fn drawn_tab_status_cell_labels_a_nonzero_terminal_exit(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let working_directory =
            std::env::temp_dir().join(format!("sirio-tab-exit-status-{}", std::process::id()));
        std::fs::create_dir_all(&working_directory).expect("create exit test directory");
        let shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exit 3".into()],
        };
        let (terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, shell, cx)
                .expect("spawn exit status test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(terminal.clone(), working_directory.clone(), cx)
        });
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            cx.run_until_parked();
            cx.background_executor
                .advance_clock(Duration::from_millis(50));
            cx.run_until_parked();
            if cx.debug_bounds("workspace-tab-exit-0").is_some() {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(
            workspace.read_with(&cx.cx, |workspace, _| {
                workspace.tabs[0].panes.contains(0)
                    && workspace.tabs[0].panes.leaf_ids().contains(&0)
            }),
            "the exit fixture keeps its terminal tab mounted"
        );
        let status_cell = cx.debug_bounds("workspace-tab-status-0").is_some();
        let error_marker = cx.debug_bounds("workspace-tab-status-error-0").is_some();
        let exit_marker = cx.debug_bounds("workspace-tab-exit-0").is_some();
        assert!(
            status_cell && error_marker && exit_marker,
            "a nonzero exit is rendered as an error status; status={:?}, exit={:?}, cell={status_cell}, error={error_marker}, exit_label={exit_marker}",
            workspace.read_with(&cx.cx, |workspace, app| {
                workspace.tab_status(&workspace.tabs[0], app)
            }),
            terminal.read_with(&cx.cx, |terminal, _| terminal.exit_status())
        );
        assert!(
            cx.debug_bounds("workspace-tab-exit-0").is_some(),
            "the tab exposes the concrete exit status"
        );
    }

    /// F-TAB-358: an exited sibling may retain its concrete exit label only
    /// while the tab has no live terminal pane to report. Once a sibling is
    /// live, its activity status is the one status shown in the tab cell.
    #[gpui::test]
    async fn drawn_split_tab_shows_live_status_without_exited_sibling_label(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let working_directory = std::env::temp_dir().join(format!(
            "sirio-tab-split-exit-status-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&working_directory)
            .expect("create split exit status test directory");
        let exited_shell = TerminalShell::WithArguments {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), "exit 0".into()],
        };
        let (exited_terminal, cx) = cx.add_window_view(|_, cx| {
            TerminalView::with_shell(&working_directory, exited_shell, cx)
                .expect("spawn exited split status test terminal")
        });
        let (workspace, cx) = cx.add_window_view(|_, cx| {
            activity_test_workspace(exited_terminal.clone(), working_directory.clone(), cx)
        });

        workspace.update(cx, |workspace, cx| {
            let live_terminal = cx.new(|cx| {
                TerminalView::with_shell(
                    &working_directory,
                    TerminalShell::WithArguments {
                        program: "/bin/sh".into(),
                        args: vec!["-c".into(), "sleep 30".into()],
                    },
                    cx,
                )
                .expect("spawn live split status test terminal")
            });
            assert!(workspace.tabs[0].panes.split_focused(
                0,
                1,
                SplitDirection::Horizontal,
                TabContent::Terminal {
                    view: live_terminal,
                },
            ));
            workspace
                .activity
                .agent_spawned("pane-1", "claude", Instant::now());
            workspace.activity.notify(
                "pane-1",
                AgentStatus::NeedsInput,
                Instant::now() + Duration::from_millis(1),
            );
            workspace.mark_activity_dirty();
            cx.notify();
        });

        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            cx.run_until_parked();
            let exited = workspace.read_with(&cx.cx, |workspace, app| {
                let mut exited = false;
                workspace.tabs[0].panes.for_each(&mut |pane_id, content| {
                    if pane_id == 0
                        && let TabContent::Terminal { view } = content
                    {
                        exited = view.read(app).exit_status().is_some();
                    }
                });
                exited
            });
            if exited {
                break;
            }
            cx.background_executor
                .advance_clock(Duration::from_millis(50));
            std::thread::sleep(Duration::from_millis(10));
        }
        cx.run_until_parked();

        let (status, exit_label) = workspace.read_with(&cx.cx, |workspace, app| {
            (
                workspace.tab_status(&workspace.tabs[0], app),
                SirioWorkspace::terminal_exit_label(&workspace.tabs[0], app),
            )
        });
        assert_eq!(
            status,
            Some(ActivityStatus::NeedsInput),
            "the live Claude pane supplies the tab status"
        );
        assert_eq!(
            exit_label, None,
            "an exited sibling must not add a second status beside the live one"
        );
        assert!(
            cx.debug_bounds("workspace-tab-status-needs-input-0")
                .is_some(),
            "the live status glyph is drawn"
        );
        assert!(
            cx.debug_bounds("workspace-tab-exit-0").is_none(),
            "the exited sibling label is not drawn beside the live status"
        );

        shutdown_workspace_terminals(&workspace, cx);
        let _ = std::fs::remove_dir_all(working_directory);
    }

    /// F-TERM-PTY-07: proves the app crate is a real caller, not just the
    /// pure `delegated_terminal_context_action` mapping this test's sibling
    /// (`terminal_context_app_actions_have_workspace_routes`) already
    /// covers. Emits the same `TerminalContextEvent` a real "Restart
    /// Terminal" menu click produces on the fixture's own live pane and
    /// confirms `subscribe_terminal`'s dispatch reaches
    /// `TerminalView::restart` and its generation actually bumps --
    /// `sirio_terminal`'s own test proves the mechanism is correct in
    /// isolation; this proves `main.rs` now calls it.
    #[gpui::test]
    async fn drawn_terminal_restart_command_reaches_the_real_pane_and_bumps_its_generation(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });
        let terminal = workspace.read_with(&cx.cx, |workspace, _| {
            let mut found = None;
            workspace.tabs[0].panes.for_each(&mut |_, content| {
                if let TabContent::Terminal { view } = content {
                    found = Some(view.clone());
                }
            });
            found.expect("the fixture's first tab is a terminal pane")
        });
        let identity = terminal.read_with(&cx.cx, |terminal, _| terminal.identity().clone());
        let generation_before =
            terminal.read_with(&cx.cx, |terminal, _| terminal.surface_generation());

        terminal.update(&mut cx.cx, |_, cx| {
            cx.emit(TerminalContextEvent {
                target: identity,
                action: TerminalContextAction::RestartTerminal,
            });
        });
        cx.run_until_parked();

        let generation_after =
            terminal.read_with(&cx.cx, |terminal, _| terminal.surface_generation());
        assert_eq!(
            generation_after,
            generation_before + 1,
            "the app crate's TerminalContextEvent dispatch must reach TerminalView::restart, \
             not just define the command"
        );
    }

    /// F-CHG-18: a changed-file row dropped onto a terminal reaches a real
    /// production `on_drop::<(PathBuf, String)>` inside `sirio_terminal`
    /// (`TerminalView::receive_diff_drop`, driven end to end by that crate's
    /// own tests), which stores the payload and emits `TerminalDropEvent`.
    /// This proves the app crate is a real subscriber of that event, not
    /// just a definition nothing outside `sirio_terminal` ever reached --
    /// the ledger's own decisive finding (`grep -rn "TerminalDropEvent"`
    /// across `sirio/src` and `sirio_ui/src` returned zero matches before
    /// this pass). Emits the exact event `receive_diff_drop` emits, on the
    /// fixture's own live terminal entity, and asserts a real Diff tab opens
    /// for the dropped file -- mirroring the macOS reference's
    /// `.requestOpenDiff(path:target:)` drop behaviour, not a stand-in.
    #[gpui::test]
    async fn drawn_terminal_diff_drop_opens_a_changes_tab_focused_on_that_file(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });
        let terminal = workspace.read_with(&cx.cx, |workspace, _| {
            let mut found = None;
            workspace.tabs[0].panes.for_each(&mut |_, content| {
                if let TabContent::Terminal { view } = content {
                    found = Some(view.clone());
                }
            });
            found.expect("the fixture's first tab is a terminal pane")
        });
        let tabs_before = workspace.read_with(&cx.cx, |workspace, _| workspace.tabs.len());
        assert!(
            !workspace.read_with(&cx.cx, |workspace, _| workspace
                .tabs
                .iter()
                .any(|tab| tab.kind == TabKind::Diff)),
            "sanity: no Diff tab exists before the drop"
        );

        let dropped_path = PathBuf::from("dropped/onto-terminal.rs");
        terminal.update(&mut cx.cx, |_, cx| {
            cx.emit(TerminalDropEvent::Diff {
                path: dropped_path.clone(),
                text: "@@ -1 +1 @@\n-old\n+new\n".to_string(),
            });
        });
        cx.run_until_parked();

        workspace.read_with(&cx.cx, |workspace, _| {
            assert_eq!(
                workspace.tabs.len(),
                tabs_before + 1,
                "dropping a diff onto a terminal must open exactly one new tab"
            );
            let new_tab = workspace.tabs.last().expect("a tab was just pushed");
            assert_eq!(
                new_tab.kind,
                TabKind::Diff,
                "the tab opened by a diff drop must be a Diff/Changes tab, \
                 not left as whatever the drop landed on"
            );
            assert_eq!(
                workspace.active_tab,
                workspace.tabs.len() - 1,
                "the newly opened Diff tab must become the active tab, the \
                 same way ChangesTabActionEvent::OpenDiff already behaves"
            );
        });
    }

