    #[test]
    fn a_chat_that_cannot_be_restored_says_why_in_readable_words() {
        let launch = test_launch_state();

        let nameless = restored_chat_refusal(&launch, None);
        assert!(
            nameless.contains("before Sirio recorded which agent"),
            "a row with no identity gets its own sentence, not a blank name: {nameless}"
        );

        let unknown = restored_chat_refusal(&launch, Some("some-retired-agent"));
        assert!(
            unknown.contains("some-retired-agent"),
            "an agent this build does not know is named back to the user: {unknown}"
        );

        // Nothing installed and no registry document: codex resolves to
        // nothing, which is exactly the case that used to vanish in silence.
        let codex = restored_chat_refusal(&launch, Some("codex"));
        assert!(
            codex.starts_with("Codex chat cannot start"),
            "the agent is named in the user's own words: {codex}"
        );
        assert!(
            !codex.contains('{') && !codex.contains("LaunchSource"),
            "no Debug formatting reaches the transcript: {codex}"
        );
    }

    #[test]
    fn restored_chat_without_a_resolvable_source_is_not_launched_at_all() {
        let mut launch = test_launch_state();
        // Nothing installed and no registry document yet: there is no honest
        // codex command, and connecting the persisted tab to ANOTHER
        // agent's server is the exact rule this work exists to enforce.
        assert!(restored_chat_spec(&launch, Some("codex")).is_none());
        assert!(restored_chat_spec(&launch, None).is_none());
        assert!(restored_chat_spec(&launch, Some("unknown-agent")).is_none());

        // An installed manifest flips it back to identity-preserving even
        // fully offline. The manifest's executable must really exist — the
        // Installed rung checks.
        let agents_root =
            std::env::temp_dir().join(format!("sirio-launch-seeded-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&agents_root);
        let executable = seed_codex_acp_manifest(&agents_root);
        launch.store = sirio_registry::InstallStore::new(agents_root);
        launch.sources = compute_launch_sources(None, &launch.store);
        let (command, icon, agent_id) =
            restored_chat_spec(&launch, Some("codex")).expect("installed source launches");
        assert_eq!(command.program, executable);
        assert_eq!(icon, Some(Icon::Codex));
        assert_eq!(agent_id.as_deref(), Some("codex"));
    }

    #[test]
    fn generic_new_chat_picks_the_first_resolved_chat_agent() {
        let mut launch = test_launch_state();
        launch.sources.clear();
        launch.sources.insert(
            "codex".into(),
            sirio_registry::LaunchSource::Builtin {
                program: "codex-acp".into(),
                args: Vec::new(),
            },
        );
        launch.sources.insert(
            "opencode".into(),
            sirio_registry::LaunchSource::Installed(sirio_registry::InstalledAgent {
                id: "opencode-acp".into(),
                version: "1.0.0".into(),
                executable: "/data/opencode-acp".into(),
                args: Vec::new(),
                integrity: sirio_registry::Integrity::Sha256,
            }),
        );

        let adapter = first_resolved_chat_adapter(&launch).expect("a chat agent is available");
        assert_eq!(adapter.id(), "codex", "catalog order is the fallback preference");
    }

