    /// Writes a codex-acp manifest whose executable really exists (the
    /// Installed rung checks `executable.exists()`). Returns the stub path.
    fn seed_codex_acp_manifest(root: &std::path::Path) -> std::path::PathBuf {
        std::fs::create_dir_all(root).unwrap();
        let executable = root.join(format!("codex-acp-stub-{}", std::process::id()));
        std::fs::write(&executable, b"stub").unwrap();
        sirio_registry::InstallStore::new(root.to_path_buf())
            .write(&sirio_registry::InstalledAgent {
                id: "codex-acp".into(),
                version: "1.6.2".into(),
                executable: executable.clone(),
                args: vec![],
                integrity: sirio_registry::Integrity::Sha256,
            })
            .unwrap();
        executable
    }

    /// Points `SIRIO_ACP_PROGRAM` at a stub file so adapter-less chat-tab
    /// fixtures exercise tab machinery instead of the (correct) refusal.
    /// Set once, process-lifetime; nothing asserts it stays unset.
    fn ensure_stub_acp_program() {
        static ONCE: std::sync::Once = std::sync::Once::new();
        ONCE.call_once(|| {
            let stub = std::env::temp_dir().join(format!("sirio-stub-acp-{}", std::process::id()));
            std::fs::write(&stub, b"stub").unwrap();
            unsafe { std::env::set_var("SIRIO_ACP_PROGRAM", &stub) };
        });
    }

    #[test]
    fn control_state_refresh_does_not_duplicate_path_ids() {
        let paths = [
            PathBuf::from("/tmp/sirio-control-id-main"),
            PathBuf::from("/tmp/sirio-control-id-preceding"),
            PathBuf::from("/tmp/sirio-control-id-survivor"),
        ];
        let worktree = |path: &Path, branch: &str, is_primary: bool| {
            session::CatalogWorktree {
                branch: branch.into(),
                path: path.to_path_buf(),
                is_primary,
            }
        };
        let initial = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "control-id-project".into(),
            name: "Control Id Project".into(),
            root_path: paths[0].clone(),
            is_git: true,
            worktrees: vec![
                worktree(&paths[0], "main", true),
                worktree(&paths[2], "survivor", false),
            ],
        }]);
        let refreshed = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "control-id-project".into(),
            name: "Control Id Project".into(),
            root_path: paths[0].clone(),
            is_git: true,
            worktrees: vec![
                worktree(&paths[0], "main", true),
                worktree(&paths[1], "preceding", false),
                worktree(&paths[2], "survivor", false),
            ],
        }]);

        let previous = ControlState::from_catalog(&initial, &paths[0]);
        let survivor_before = previous
            .workspaces
            .iter()
            .find(|workspace| workspace.path == paths[2].to_string_lossy())
            .expect("initial survivor row")
            .id
            .clone();
        let mut next = ControlState::from_catalog(&refreshed, &paths[0]);
        next.preserve_runtime_state_from(&previous);

        let ids: Vec<String> = next
            .workspaces
            .iter()
            .map(|workspace| workspace.id.clone())
            .collect();
        let unique_ids: HashSet<String> = ids.iter().cloned().collect();
        assert_eq!(unique_ids.len(), ids.len(), "refresh must not duplicate workspace ids");
        let survivor_after = next
            .workspaces
            .iter()
            .find(|workspace| workspace.path == paths[2].to_string_lossy())
            .expect("refreshed survivor row")
            .id
            .clone();
        assert_eq!(survivor_after, survivor_before);
    }

    #[test]
    fn selecting_a_worktree_updates_current_and_row_flags() {
        let main_path = PathBuf::from("/tmp/sirio-selection-main");
        let feature_path = PathBuf::from("/tmp/sirio-selection-feature");
        let catalog = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "project".into(),
            name: "sirio".into(),
            root_path: main_path.clone(),
            is_git: true,
            worktrees: vec![
                session::CatalogWorktree {
                    branch: "main".into(),
                    path: main_path.clone(),
                    is_primary: true,
                },
                session::CatalogWorktree {
                    branch: "feature".into(),
                    path: feature_path.clone(),
                    is_primary: false,
                },
            ],
        }]);
        let mut state = ControlState::from_catalog(&catalog, &main_path);
        let expected_path = feature_path.to_string_lossy().into_owned();

        assert_eq!(state.current, Some(0));
        assert_eq!(
            state
                .workspaces
                .iter()
                .map(|workspace| workspace.selected)
                .collect::<Vec<_>>(),
            vec![true, false]
        );

        assert!(state.select_worktree(&feature_path));

        assert_eq!(state.current, Some(1));
        assert_eq!(
            state
                .workspaces
                .iter()
                .map(|workspace| workspace.selected)
                .collect::<Vec<_>>(),
            vec![false, true]
        );
        assert_eq!(
            state
                .current_workspace()
                .map(|workspace| workspace.path.as_str()),
            Some(expected_path.as_str())
        );
    }

