    /// F-CORE-ACT-25: `ControlState::from_catalog` runs the restored
    /// worktree list through `BootstrapRestoreOrder::partition` -- only the
    /// selected worktree (the sole "previously open" id a single-directory
    /// launch snapshot recovers) starts mounted; every deferred worktree
    /// starts unmounted rather than the old "mount everything" default.
    #[test]
    fn bootstrap_restore_order_mounts_only_the_selected_worktree_at_first_paint() {
        let main_path = PathBuf::from("/tmp/sirio-bootstrap-main");
        let feature_path = PathBuf::from("/tmp/sirio-bootstrap-feature");
        let other_path = PathBuf::from("/tmp/sirio-bootstrap-other");
        let catalog = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "project".into(),
            name: "sirio".into(),
            root_path: main_path.clone(),
            is_git: true,
            worktrees: vec![
                session::CatalogWorktree {
                    branch: "main".into(),
                    path: main_path.clone(),
                    is_primary: true,
                },
                session::CatalogWorktree {
                    branch: "feature".into(),
                    path: feature_path.clone(),
                    is_primary: false,
                },
                session::CatalogWorktree {
                    branch: "other".into(),
                    path: other_path.clone(),
                    is_primary: false,
                },
            ],
        }]);
        let state = ControlState::from_catalog(&catalog, &feature_path);

        assert_eq!(
            state
                .workspaces
                .iter()
                .map(|workspace| (workspace.path.clone(), workspace.mounted))
                .collect::<Vec<_>>(),
            vec![
                (main_path.to_string_lossy().into_owned(), false),
                (feature_path.to_string_lossy().into_owned(), true),
                (other_path.to_string_lossy().into_owned(), false),
            ]
        );
    }

    /// The two refreshes `render` runs on the false→true `is_window_active`
    /// transition (#114) -- the user minimised the app or clicked another
    /// window, then came back -- each rebuild the sidebar rows from the
    /// catalog. The rebuild must keep the tab rows a worktree was listing:
    /// before the fix `refresh_sidebar` dropped them and re-applied only the
    /// agent facts, so a worktree with open chats lost its rows and, with
    /// them, its chevron until some unrelated activity reconcile happened
    /// to run.
    #[gpui::test]
    async fn regaining_window_focus_keeps_a_worktrees_tab_rows_and_chevron(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let repo = committed_test_repo("focus-regain-tab-rows");
        let repo_for_constructor = repo.clone();
        let workspace = cx.new(|cx| {
            // One live terminal tab (id 0), owned by the repo's worktree.
            let mut workspace = palette_test_workspace(cx);
            let project_catalog =
                ProjectCatalog::from_projects(vec![session::CatalogProject {
                    id: "focus-regain-project".into(),
                    name: "Focus Regain Project".into(),
                    root_path: repo_for_constructor.clone(),
                    is_git: true,
                    worktrees: vec![session::CatalogWorktree {
                        branch: "main".into(),
                        path: repo_for_constructor.clone(),
                        is_primary: true,
                    }],
                }]);
            workspace.working_directory = repo_for_constructor.clone();
            for tab in &workspace.tabs {
                workspace
                    .tab_worktree_paths
                    .insert(tab.id, repo_for_constructor.clone());
            }
            workspace.control_state = Arc::new(Mutex::new(ControlState::from_catalog(
                &project_catalog,
                &repo_for_constructor,
            )));
            workspace.project_catalog = project_catalog;
            workspace.refresh_sidebar(cx);
            // The frame's own reconcile lists the open tab under its row.
            workspace.mark_activity_dirty();
            workspace.sync_activity(cx);
            workspace
        });

        let worktree_id = workspace.update(cx, |workspace, _cx| {
            workspace
                .sidebar_worktree_id(&repo)
                .expect("the repo's worktree has a sidebar row")
        });
        let before = workspace.update(cx, |workspace, cx| {
            let before = workspace
                .sidebar
                .read(cx)
                .worktree_disclosure(worktree_id)
                .expect("the worktree row exists before any refresh");
            assert_eq!(
                before.1.len(),
                1,
                "the worktree lists its one open terminal tab: {before:?}"
            );
            assert!(before.0, "a worktree with tab rows starts expanded");
            before
        });

        // Step one of the focus-regain branch in `render`: fire-and-forget,
        // so the sidebar must be untouched the instant the call returns --
        // the git subprocess work only runs once the background task is
        // polled.
        workspace.update(cx, |workspace, cx| {
            let working_directory = workspace.working_directory.clone();
            workspace.refresh_project_for_path_in_background(&working_directory, cx);
        });
        let immediately_after = workspace.update(cx, |workspace, cx| {
            workspace.sidebar.read(cx).worktree_disclosure(worktree_id)
        });
        assert_eq!(
            immediately_after,
            Some(before.clone()),
            "refresh_project_for_path_in_background must not block render: the sidebar is unchanged the instant the call returns"
        );

        cx.run_until_parked();

        let after_project_refresh = workspace.update(cx, |workspace, cx| {
            workspace.sidebar.read(cx).worktree_disclosure(worktree_id)
        });
        assert_eq!(
            after_project_refresh,
            Some(before.clone()),
            "refresh_project_for_path_in_background must keep the worktree's tab rows (and so its chevron) once the background refresh lands"
        );

        // Step two, made to actually rebuild: HEAD moved while the app was
        // in the background, exactly the #114 case.
        git_test(&repo, &["checkout", "-q", "-b", "switched-while-unfocused"]);
        workspace.update(cx, |workspace, cx| {
            assert!(
                workspace.refresh_worktree_branches(cx),
                "the branch flip under the app must be noticed"
            );
            let after_branch_refresh = workspace
                .sidebar
                .read(cx)
                .worktree_disclosure(worktree_id);
            assert_eq!(
                after_branch_refresh,
                Some(before),
                "refresh_worktree_branches must keep the worktree's tab rows (and so its chevron)"
            );
        });
    }

    /// The same rebuild, for a worktree the user is not looking at: its
    /// chats are parked rows built from its persisted strip, which the
    /// reconcile reads once and caches. A refresh re-lists them from that
    /// cache and never reads the strip itself (`ParkedRows::CachedOnly`),
    /// so the first read stays with the reconcile, as the cache's doc
    /// promises.
    #[gpui::test]
    async fn regaining_window_focus_keeps_an_unselected_worktrees_parked_rows(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let repo = committed_test_repo("focus-regain-parked-rows");
        let other = parked_rows_other_dir(&repo);
        let (repo_for_constructor, other_for_constructor) = (repo.clone(), other.clone());
        let workspace = cx.new(|cx| {
            let workspace =
                parked_rows_test_workspace(cx, &repo_for_constructor, &other_for_constructor);
            workspace.session.save_layout_now(&persisted_layout(
                &other_for_constructor,
                "other",
                vec![
                    persisted_chat("other-a", "Other A", true),
                    persisted_chat("other-b", "Other B", false),
                ],
            ));
            workspace
        });

        let other_id = workspace.update(cx, |workspace, cx| {
            let other_id = workspace
                .sidebar_worktree_id(&other)
                .expect("the second worktree has a sidebar row");
            // The reconcile reads the strip once and lists it as parked rows.
            workspace.mark_activity_dirty();
            workspace.sync_activity(cx);
            other_id
        });
        let before = workspace.update(cx, |workspace, cx| {
            let before = workspace
                .sidebar
                .read(cx)
                .worktree_disclosure(other_id)
                .expect("the second worktree row exists before any refresh");
            assert_eq!(
                before.1,
                vec![
                    parked_tab_row_id(other_id, 0),
                    parked_tab_row_id(other_id, 1)
                ],
                "the unselected worktree lists its two persisted chats as parked rows: {before:?}"
            );
            assert!(before.0, "a worktree with parked rows starts expanded");
            before
        });

        // Fire-and-forget: the parked rows must be untouched the instant the
        // call returns, before the background refresh has had a chance to
        // run.
        workspace.update(cx, |workspace, cx| {
            let working_directory = workspace.working_directory.clone();
            workspace.refresh_project_for_path_in_background(&working_directory, cx);
        });
        let immediately_after = workspace.update(cx, |workspace, cx| {
            workspace.sidebar.read(cx).worktree_disclosure(other_id)
        });
        assert_eq!(
            immediately_after,
            Some(before.clone()),
            "refresh_project_for_path_in_background must not block render: the parked rows are unchanged the instant the call returns"
        );

        cx.run_until_parked();

        let after = workspace.update(cx, |workspace, cx| {
            workspace.sidebar.read(cx).worktree_disclosure(other_id)
        });
        assert_eq!(
            after,
            Some(before),
            "refresh_project_for_path_in_background must keep the unselected worktree's parked rows (and so its chevron) once the background refresh lands"
        );
    }

    /// #114: a catalog row's branch label must follow what its checkout
    /// actually says — including after a real `git checkout -b` flips
    /// branches under the running app — and a call over an unchanged HEAD
    /// must report `false`, i.e. never notify, or the app would redraw
    /// forever on no-op refreshes.
    #[gpui::test]
    async fn refresh_worktree_branches_follows_head_changes_and_stays_quiet_when_stable(
        cx: &mut TestAppContext,
    ) {
        cx.set_global(Theme::light());
        let repo = test_repo("live-branch-label");
        std::fs::write(repo.join("file.txt"), "one\n").expect("seed fixture file");
        git_test(&repo, &["add", "--", "file.txt"]);
        git_test(&repo, &["commit", "-m", "root"]);
        // A second row whose checkout has no `.git` at all: its stored
        // label is all Sirio knows about it and must survive every
        // refresh rather than be blanked by an unreadable HEAD.
        let no_git_dir =
            std::env::temp_dir().join(format!("sirio-live-label-nogit-{}", std::process::id()));
        std::fs::create_dir_all(&no_git_dir).expect("create non-repo fixture dir");

        let repo_for_constructor = repo.clone();
        let workspace = cx.new(|cx| {
            let mut workspace = palette_test_workspace(cx);
            workspace.project_catalog =
                ProjectCatalog::from_projects(vec![session::CatalogProject {
                    id: "sirio".into(),
                    name: "sirio".into(),
                    root_path: repo_for_constructor.clone(),
                    is_git: true,
                    worktrees: vec![
                        session::CatalogWorktree {
                            // Deliberately NOT what HEAD ("main") says: stale
                            // exactly the way a label discovered before an
                            // agent switched branches goes stale.
                            branch: "stale-side-branch".into(),
                            path: repo_for_constructor.clone(),
                            is_primary: true,
                        },
                        session::CatalogWorktree {
                            branch: "kept-as-is".into(),
                            path: no_git_dir.clone(),
                            is_primary: false,
                        },
                    ],
                }]);
            workspace
        });

        workspace.update(cx, |workspace, cx| {
            assert!(
                workspace.refresh_worktree_branches(cx),
                "the stale row disagrees with the checkout's real HEAD ('main'); \
                 the first refresh must correct it"
            );
            let rows = &workspace.project_catalog.projects()[0].worktrees;
            assert_eq!(rows[0].branch, "main");
            assert_eq!(
                rows[1].branch, "kept-as-is",
                "a checkout whose HEAD cannot be read keeps the label it had"
            );
            assert!(
                !workspace.refresh_worktree_branches(cx),
                "nothing changed since the last refresh -- returning true here \
                 would notify and redraw forever"
            );
        });

        // The exact #114 event: the branch flips outside the app while it
        // runs. No restart, no rediscovery -- the next refresh reads it.
        git_test(&repo, &["checkout", "-b", "switched-underneath"]);
        workspace.update(cx, |workspace, cx| {
            assert!(
                workspace.refresh_worktree_branches(cx),
                "HEAD changed under the app; the next refresh must notice"
            );
            assert_eq!(
                workspace.project_catalog.projects()[0].worktrees[0].branch,
                "switched-underneath"
            );
            assert!(
                !workspace.refresh_worktree_branches(cx),
                "the now-current label must stop the notifies again"
            );
        });
    }

    /// #114 follow-up: the refreshed label was only written to
    /// `project_catalog`, so the rows the user sees and the socket answers kept
    /// their stale copy. This asserts the socket-visible copy follows, read back
    /// through the same `ControlState`/`current_workspace()` path `workspace.list`
    /// and `workspace.current` use. Before the fix this fails with
    /// `left: "main"` / `right: "switched-underneath"` (or with the stale
    /// initial label) because nothing republished the catalog to the control
    /// state.
    #[gpui::test]
    async fn refresh_worktree_branches_publishes_to_control_state(cx: &mut TestAppContext) {
        cx.set_global(Theme::light());
        let repo = test_repo("live-branch-label-control-state");
        std::fs::write(repo.join("file.txt"), "one\n").expect("seed fixture file");
        git_test(&repo, &["add", "--", "file.txt"]);
        git_test(&repo, &["commit", "-m", "root"]);

        let repo_for_constructor = repo.clone();
        let repo_for_state = repo.clone();
        let workspace = cx.new(|cx| {
            let mut workspace = palette_test_workspace(cx);
            workspace.working_directory = repo_for_constructor.clone();
            workspace.project_catalog =
                ProjectCatalog::from_projects(vec![session::CatalogProject {
                    id: "sirio".into(),
                    name: "sirio".into(),
                    root_path: repo_for_constructor.clone(),
                    is_git: true,
                    worktrees: vec![session::CatalogWorktree {
                        branch: "stale-side-branch".into(),
                        path: repo_for_constructor.clone(),
                        is_primary: true,
                    }],
                }]);
            // Keep ControlState in lock-step with the stale catalog so the
            // `current_workspace().branch` we read afterwards is not a stale
            // `palette_test_workspace` leftover. `refresh_worktree_branches`
            // must itself republish to both surfaces.
            workspace.sync_control_state();
            workspace
        });

        workspace.update(cx, |workspace, cx| {
            assert!(
                workspace.refresh_worktree_branches(cx),
                "stale label must be corrected on first refresh"
            );
            let catalog_branch = workspace.project_catalog.projects()[0].worktrees[0]
                .branch
                .clone();
            assert_eq!(catalog_branch, "main");
            // Read back through the socket-visible copy, not the catalog.
            // `current_workspace()` can be None when `working_directory` has not
            // yet been canonicalised to match the worktree path inside the
            // test's throwaway temp dir (Windows `canonicalize` subtleties), so
            // read the workspaces row directly — it is the same `ControlState`
            // `workspace.list`/`workspace.current` answer from.
            let control_branch = workspace
                .control_state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .workspaces
                .first()
                .expect("control state has a workspace row")
                .branch
                .clone();
            assert_eq!(
                control_branch, "main",
                "ControlState must follow the catalog on first refresh — \
                 before the fix it kept the stale label"
            );
        });

        git_test(&repo_for_state, &["checkout", "-b", "switched-underneath"]);
        workspace.update(cx, |workspace, cx| {
            assert!(
                workspace.refresh_worktree_branches(cx),
                "HEAD changed under the app; the next refresh must notice"
            );
            let catalog_branch = workspace.project_catalog.projects()[0].worktrees[0]
                .branch
                .clone();
            assert_eq!(catalog_branch, "switched-underneath");
            let control_branch = workspace
                .control_state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .workspaces
                .first()
                .expect("control state still has a workspace row")
                .branch
                .clone();
            assert_eq!(
                control_branch, "switched-underneath",
                "ControlState must follow the catalog after a branch switch — \
                 before the fix workspace.list/current kept the old branch"
            );
        });

        // Sidebar rows cannot be asserted without a drawn test; those fail on
        // this machine, so the ControlState assertion above stands as the guard.
    }

    #[test]
    fn primary_context_transition_updates_one_catalog_worktree() {
        let main_path = PathBuf::from("/tmp/sirio-primary-main");
        let feature_path = PathBuf::from("/tmp/sirio-primary-feature");
        let mut catalog = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "project".into(),
            name: "sirio".into(),
            root_path: main_path.clone(),
            is_git: true,
            worktrees: vec![
                session::CatalogWorktree {
                    branch: "main".into(),
                    path: main_path.clone(),
                    is_primary: true,
                },
                session::CatalogWorktree {
                    branch: "feature".into(),
                    path: feature_path.clone(),
                    is_primary: false,
                },
            ],
        }]);

        catalog
            .set_primary(&feature_path, true)
            .expect("known worktree can become primary");
        assert_eq!(
            catalog.projects()[0]
                .worktrees
                .iter()
                .map(|worktree| worktree.is_primary)
                .collect::<Vec<_>>(),
            vec![false, true]
        );

        catalog
            .set_primary(&feature_path, false)
            .expect("known primary can be unset");
        assert!(
            catalog.projects()[0]
                .worktrees
                .iter()
                .all(|worktree| { !worktree.is_primary })
        );
    }

