    /// The test whose absence let `right_panel_width` sit in the settings model
    /// for months with a clamp, a test, and no reader: it compares the *drawn*
    /// panel against the *configured* width. The pre-existing geometry tests
    /// compare drawn bounds against the constant the render code itself reads,
    /// so they cannot fail when the render ignores configuration — they assert
    /// that 405 == 405.
    #[gpui::test]
    async fn a_configured_panel_width_is_the_width_actually_drawn(cx: &mut TestAppContext) {
        cx.set_global(Theme::dark());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });

        // 280 + 380 = 660, deliberately inside the test window's budget. The
        // gpui test window is 1024x768, so budget = 1024 - 8 - 8 - 320 = 688.
        // Asking for more (500 on the right, say) makes the resolver correctly
        // narrow the panels and this test then fails against perfectly good
        // wiring — a false red that looks exactly like a real one.
        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.sidebar_width = 280.0;
            workspace.right_panel_width = 380.0;
            cx.notify();
        });
        cx.run_until_parked();

        let left = cx.debug_bounds("shell-left-panel").expect("left panel");
        let right = cx.debug_bounds("shell-right-panel").expect("right panel");

        assert_eq!(left.size.width, px(280.0));
        assert_eq!(right.size.width, px(380.0));
    }

    /// Dragging the right panel's inner edge leftwards makes it wider, because
    /// that edge is its left border. The handle is drawn out of layout flow, so
    /// this must not disturb the 4px shell gaps the geometry tests pin.
    #[gpui::test]
    async fn dragging_the_right_panel_edge_changes_its_drawn_width(cx: &mut TestAppContext) {
        cx.set_global(Theme::dark());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });

        // Start from widths that fit, so rendered == preferred and the assertion
        // below measures the drag rather than the viewport clamp. The gpui test
        // window is 1024 wide (budget 688); the shipped defaults are 325 + 405 =
        // 730, which the resolver would correctly narrow — and then `before`
        // would not be the preference this drag is moving.
        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.sidebar_width = 280.0;
            workspace.right_panel_width = 300.0;
            cx.notify();
        });
        cx.run_until_parked();

        let before = cx.debug_bounds("shell-right-panel").expect("right panel");
        let handle = cx
            .debug_bounds("panel-resize-right")
            .expect("resize handle");
        let centre = cx.debug_bounds("shell-center-panel").expect("centre panel");
        assert_eq!(
            before.size.width,
            px(300.0),
            "baseline: nothing is clamped yet"
        );

        // Hover first, as a real pointer would, then press.
        cx.simulate_event(MouseMoveEvent {
            position: handle.center(),
            pressed_button: None,
            modifiers: Modifiers::none(),
        });
        cx.run_until_parked();
        cx.simulate_event(MouseDownEvent {
            position: handle.center(),
            button: MouseButton::Left,
            modifiers: Modifiers::none(),
            click_count: 1,
            first_mouse: false,
        });
        // Two moves, not one. The first crosses GPUI's drag-start threshold and
        // is swallowed; only the second reaches `on_drag_move`. The codebase's
        // other drag tests (`drawn_divider_drag_leaves_pane_focus_untouched`,
        // `main.rs:16603`) carry the same comment — a single move here silently
        // asserts nothing.
        cx.simulate_event(MouseMoveEvent {
            position: point(handle.center().x - px(4.0), handle.center().y),
            pressed_button: Some(MouseButton::Left),
            modifiers: Modifiers::none(),
        });
        cx.simulate_event(MouseMoveEvent {
            position: point(handle.center().x - px(60.0), handle.center().y),
            pressed_button: Some(MouseButton::Left),
            modifiers: Modifiers::none(),
        });
        cx.run_until_parked();

        let after = cx.debug_bounds("shell-right-panel").expect("right panel");
        assert_eq!(
            after.size.width,
            before.size.width + px(60.0),
            "dragging the left border leftwards widens the right panel"
        );

        let centre_after = cx.debug_bounds("shell-center-panel").expect("centre panel");
        assert_eq!(
            after.left() - centre_after.right(),
            px(4.0),
            "the shell gap is untouched: the handle is out of layout flow"
        );
        assert!(centre_after.size.width < centre.size.width);
    }

    /// Resizing a panel must not cost the focused pane its keyboard focus.
    /// GPUI clears focus after mouse-down and a next-frame re-focus loses the
    /// race, so `on_drop` is the only place the restore sticks — and this is what
    /// proves it does.
    #[gpui::test]
    async fn dragging_a_panel_edge_leaves_the_focused_pane_focused(cx: &mut TestAppContext) {
        cx.set_global(Theme::dark());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });

        // Capture the focused pane's handle the same way
        // `drawn_divider_drag_leaves_pane_focus_untouched` (main.rs:16603) does,
        // and assert the baseline before touching anything: a test that cannot
        // observe a real focus change proves nothing when focus does not move.
        //
        // The headless fixture starts with *nobody* focused (no window was
        // ever clicked), so the pane is given focus explicitly first — the
        // same setup `moving_a_tab_to_another_pane_returns_focus_to_the_moved_tab`
        // uses — and the baseline then proves the handle observes real focus.
        let focus = workspace.read_with(&cx.cx, |workspace, cx| {
            let tab = &workspace.tabs[workspace.active_tab];
            let mut handle = None;
            tab.panes.for_each(&mut |id, content| {
                let TabContent::Terminal { view } = content else {
                    return;
                };
                if id == tab.focused_pane {
                    handle = Some(view.focus_handle(cx));
                }
            });
            handle.expect("the palette test workspace has a terminal pane")
        });
        cx.update(|window, app| focus.focus(window, app));
        cx.run_until_parked();
        cx.update(|window, _| {
            assert!(
                focus.is_focused(window),
                "baseline: the pane starts focused"
            );
        });

        let handle = cx
            .debug_bounds("panel-resize-right")
            .expect("resize handle");
        let start = handle.center();

        cx.simulate_event(MouseMoveEvent {
            position: start,
            pressed_button: None,
            modifiers: Modifiers::none(),
        });
        cx.run_until_parked();
        cx.simulate_event(MouseDownEvent {
            position: start,
            button: MouseButton::Left,
            modifiers: Modifiers::none(),
            click_count: 1,
            first_mouse: false,
        });
        cx.simulate_event(MouseMoveEvent {
            position: point(start.x - px(4.0), start.y),
            pressed_button: Some(MouseButton::Left),
            modifiers: Modifiers::none(),
        });
        cx.simulate_event(MouseMoveEvent {
            position: point(start.x - px(30.0), start.y),
            pressed_button: Some(MouseButton::Left),
            modifiers: Modifiers::none(),
        });
        cx.simulate_event(MouseUpEvent {
            position: point(start.x - px(30.0), start.y),
            button: MouseButton::Left,
            modifiers: Modifiers::none(),
            click_count: 1,
        });
        cx.run_until_parked();

        cx.update(|window, _| {
            assert!(
                focus.is_focused(window),
                "the drop must hand focus back to the pane"
            );
        });
        workspace.read_with(&cx.cx, |workspace, _| {
            assert_eq!(
                workspace.dragging_panel, None,
                "the drop clears drag priority, so the panels stop favouring one side"
            );
        });
    }

    /// A drag writes to SQLite after it settles, not once per frame: nothing is
    /// stored while the width is still moving, and the width that lands is the
    /// last one asked for.
    ///
    /// What this test does *not* prove is a literal write count — that would need
    /// a spy `SessionStore`, which this codebase has no seam for. What it does
    /// prove is the property the debounce exists for: two superseded schedules
    /// leave no trace.
    ///
    /// The debounce is a gpui timer rather than the `std::thread::sleep` shape
    /// `Terminal::resize` uses, precisely so `advance_clock` can drive it:
    /// neither that sleep nor the session flusher's `Instant::now` polling can be
    /// advanced by the executor, and a test for either would have to sleep for
    /// real.
    #[gpui::test]
    async fn panel_width_persists_once_after_the_drag_settles(cx: &mut TestAppContext) {
        cx.set_global(Theme::dark());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });

        for width in [420.0, 440.0, 460.0] {
            workspace.update(&mut cx.cx, |workspace, cx| {
                workspace.right_panel_width = width;
                workspace.schedule_panel_width_save(cx);
            });
        }
        cx.run_until_parked();

        let session = workspace.read_with(&cx.cx, |workspace, _| workspace.session.clone());
        assert_eq!(
            session.load_settings().right_panel_width,
            405,
            "nothing is written while the drag is still moving"
        );

        cx.background_executor
            .advance_clock(PANEL_WIDTH_SAVE_DEBOUNCE);
        cx.run_until_parked();

        assert_eq!(
            session.load_settings().right_panel_width,
            460,
            "the last width wins, and only it is written"
        );
    }

    #[gpui::test]
    async fn mixed_sidebar_visibility_keeps_the_center_inset_and_gap(cx: &mut TestAppContext) {
        cx.set_global(Theme::dark());
        let window = cx.add_window(|_window, cx| palette_test_workspace(cx));
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let workspace = cx.update(|window, _| {
            window
                .root::<SirioWorkspace>()
                .flatten()
                .expect("workspace root")
        });
        let both_visible_center = cx.debug_bounds("shell-center-panel").expect("center panel");
        let (workspace_sidebar_width, workspace_right_panel_width) = workspace
            .read_with(&cx.cx, |workspace, _| {
                (workspace.sidebar_width, workspace.right_panel_width)
            });

        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.sidebar_visible = false;
            cx.notify();
        });
        cx.run_until_parked();

        assert!(cx.debug_bounds("shell-left-panel").is_none());
        let work = cx.debug_bounds("shell-work-area").expect("work area");
        let center = cx.debug_bounds("shell-center-panel").expect("center panel");
        let right = cx.debug_bounds("shell-right-panel").expect("right panel");
        assert_eq!(
            center.size.width - both_visible_center.size.width,
            px(workspace_sidebar_width + 4.0)
        );
        assert_eq!(right.left() - center.right(), px(4.0));
        assert_eq!(center.left() - work.left(), px(4.0));
        assert!(center.size.height > px(0.0));
        assert_eq!(center.top() - work.top(), px(4.0));
        assert_eq!(work.bottom() - center.bottom(), px(4.0));

        workspace.update(&mut cx.cx, |workspace, cx| {
            workspace.sidebar_visible = true;
            workspace.right_panel_visible = false;
            cx.notify();
        });
        cx.run_until_parked();

        assert!(cx.debug_bounds("shell-right-panel").is_none());
        let work = cx.debug_bounds("shell-work-area").expect("work area");
        let left = cx.debug_bounds("shell-left-panel").expect("left panel");
        let center = cx.debug_bounds("shell-center-panel").expect("center panel");
        assert_eq!(
            center.size.width - both_visible_center.size.width,
            px(workspace_right_panel_width + 4.0)
        );
        assert_eq!(center.left() - left.right(), px(4.0));
        assert_eq!(work.right() - center.right(), px(4.0));
        assert!(center.size.height > px(0.0));
        assert_eq!(center.top() - work.top(), px(4.0));
        assert_eq!(work.bottom() - center.bottom(), px(4.0));
    }

    #[test]
    fn center_available_width_accounts_for_visible_shell_panels_and_gaps() {
        let viewport_width = 1_000.0;
        let outer_inset = 4.0;
        let gap = 4.0;
        // Named rather than inlined: these used to be 405 and 325 in
        // disguise, which is exactly why the numbers below never moved when
        // the panels were meant to become resizable.
        let sidebar = 325.0;
        let right = 405.0;

        assert_eq!(
            center_available_width_for_shell(
                viewport_width,
                Some(sidebar),
                Some(right),
                outer_inset,
                gap
            ),
            viewport_width - sidebar - right - (2.0 * gap) - (2.0 * outer_inset),
        );
        assert_eq!(
            center_available_width_for_shell(viewport_width, Some(sidebar), None, outer_inset, gap),
            viewport_width - sidebar - gap - (2.0 * outer_inset),
        );
        assert_eq!(
            center_available_width_for_shell(viewport_width, None, Some(right), outer_inset, gap),
            viewport_width - right - gap - (2.0 * outer_inset),
        );
        assert_eq!(
            center_available_width_for_shell(viewport_width, None, None, outer_inset, gap),
            viewport_width - (2.0 * outer_inset),
        );
    }

    #[test]
    fn surface_methods_are_advertised_by_capabilities() {
        let handler = AppControlHandler::new(
            Arc::new(Mutex::new(ControlState {
                projects: Vec::new(),
                project_settings: BTreeMap::new(),
                workspaces: Vec::new(),
                current: None,
            })),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(PathBuf::from("/tmp/sirio-surface-test.sock")),
        );

        let response = handler.handle(&ControlRequest {
            id: "capabilities".into(),
            method: "system.capabilities".into(),
            params: BTreeMap::new(),
        });
        let methods = response
            .result
            .as_ref()
            .and_then(|result| result.get("methods"))
            .and_then(|encoded| sirio_control::protocol::rows::decode(encoded))
            .expect("capability rows");
        for method in [
            "project.list",
            "project.add",
            "panel.state",
            "panel.scrollback",
            "surface.changes.open",
            "surface.changes.read",
            "surface.changes.stage",
            "surface.changes.unstage",
            "surface.changes.discard",
            "surface.changes.stage_all",
            "surface.changes.discard_all",
            "surface.settings.open",
            "surface.settings.select",
            "surface.settings.read",
        ] {
            assert!(
                methods
                    .iter()
                    .any(|row| row.get("method").map(String::as_str) == Some(method)),
                "{method} must be advertised"
            );
        }
    }

    #[cfg(any())]
    #[test]
    fn chat_surface_methods_are_advertised_and_reach_the_app_handler() {
        let handler = AppControlHandler::new(
            Arc::new(Mutex::new(ControlState {
                projects: Vec::new(),
                project_settings: BTreeMap::new(),
                workspaces: Vec::new(),
                current: None,
            })),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(PathBuf::from("/tmp/sirio-chat-dispatch-test.sock")),
        );

        let capabilities = handler.handle(&ControlRequest {
            id: "capabilities".into(),
            method: "system.capabilities".into(),
            params: BTreeMap::new(),
        });
        let methods = capabilities
            .result
            .as_ref()
            .and_then(|result| result.get("methods"))
            .and_then(|encoded| sirio_control::protocol::rows::decode(encoded))
            .expect("capability rows");
        for method in [
            "surface.chat.open",
            "surface.chat.send",
            "surface.chat.compose",
            "surface.chat.permission",
            "surface.chat.stop",
            "surface.chat.read",
        ] {
            assert!(
                methods
                    .iter()
                    .any(|row| row.get("method").map(String::as_str) == Some(method)),
                "{method} must be advertised"
            );
        }

        for (index, method) in [
            "surface.chat.send",
            "surface.chat.compose",
            "surface.chat.permission",
            "surface.chat.stop",
            "surface.chat.read",
        ]
        .into_iter()
        .enumerate()
        {
            let mut params = BTreeMap::from([(String::from("surfaceId"), String::from("missing"))]);
            match method {
                "surface.chat.send" | "surface.chat.compose" => {
                    params.insert("text".into(), "input".into());
                }
                "surface.chat.permission" => {
                    params.insert("requestId".into(), "1".into());
                    params.insert("optionId".into(), "deny".into());
                }
                "surface.chat.stop" | "surface.chat.read" => {}
                _ => unreachable!("chat dispatch test method is exhaustive"),
            }
            let response = handler.handle(&ControlRequest {
                id: format!("chat-dispatch-{index}"),
                method: method.into(),
                params,
            });
            assert!(!response.ok, "unopened {method} must fail");
            let expected_error = if method == "surface.chat.read" {
                "unknown chat surface: missing"
            } else {
                "chat surface is not open: missing"
            };
            assert!(
                response
                    .error
                    .as_deref()
                    .is_some_and(|error| error == expected_error),
                "{method} must report an unopened surface: {response:?}"
            );
            assert_ne!(
                response.error.as_deref(),
                Some(format!("unknown control method: {method}").as_str()),
                "{method} must reach its chat handler"
            );
        }
    }

    /// `surface.chat.read` keeps `queuedText` as the front entry for the
    /// readers that predate the multi-entry queue (D-CHAT-03) and adds
    /// `queued`, the whole queue front first, as encoded rows.
    #[test]
    fn control_chat_result_exposes_the_whole_queue() {
        let snapshot = ChatControlSnapshot {
            status: "streaming".into(),
            composer_text: String::new(),
            queued_text: "a".into(),
            queued: vec!["a".into(), "b".into()],
            transcript: Vec::new(),
        };
        let result: BTreeMap<String, String> =
            SirioWorkspace::control_chat_result("surface-1", snapshot)
                .into_iter()
                .collect();
        assert_eq!(
            result.get("queuedText").map(String::as_str),
            Some("a"),
            "queuedText stays the front entry"
        );
        let queued = sirio_control::protocol::rows::decode(
            result.get("queued").expect("the queued rows are present"),
        )
        .expect("the queued rows decode");
        assert_eq!(
            queued
                .iter()
                .map(|row| row.get("text").cloned().unwrap_or_default())
                .collect::<Vec<_>>(),
            vec!["a".to_string(), "b".to_string()],
            "queued carries every entry, front first"
        );
    }

    #[test]
    fn chat_compose_is_queued_for_the_rendered_chat_entity() {
        let actions = Arc::new(Mutex::new(Vec::new()));
        let handler = Arc::new(AppControlHandler::new(
            Arc::new(Mutex::new(ControlState {
                projects: Vec::new(),
                project_settings: BTreeMap::new(),
                workspaces: Vec::new(),
                current: None,
            })),
            actions.clone(),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(PathBuf::from("/tmp/sirio-chat-queue-test.sock")),
        ));
        let request = ControlRequest {
            id: "chat-compose".into(),
            method: "surface.chat.compose".into(),
            params: BTreeMap::from([
                ("surfaceId".into(), "default-chat".into()),
                ("text".into(), "MARKER_P107".into()),
            ]),
        };
        let worker = std::thread::spawn({
            let handler = handler.clone();
            move || handler.handle(&request)
        });

        let action = loop {
            if let Some(action) = actions.lock().expect("action queue").pop() {
                break action;
            }
            std::thread::yield_now();
        };
        let ControlAction::Chat {
            action: ChatControlAction::Compose { surface_id, text },
            reply,
        } = action
        else {
            panic!("compose must cross the existing GPUI control-action queue");
        };
        assert_eq!(surface_id, "default-chat");
        assert_eq!(text, "MARKER_P107");
        reply
            .send(Ok(vec![("composerText".into(), "MARKER_P107".into())]))
            .expect("reply to socket worker");
        let response = worker.join().expect("socket worker did not panic");
        assert!(response.ok, "queued compose response: {response:?}");
    }

    #[cfg(any())]
    fn app_chat_read(socket_path: &Path, surface_id: &str) -> BTreeMap<String, String> {
        let response = sirio_control::round_trip(
            socket_path,
            &sirio_control::protocol::request::chat_read(surface_id),
            Duration::from_secs(5),
        )
        .expect("chat read round trip");
        assert!(response.ok, "chat read failed: {response:?}");
        response.result.expect("chat read result")
    }

    #[cfg(any())]
    fn wait_for_app_chat_read<F>(
        socket_path: &Path,
        surface_id: &str,
        mut predicate: F,
    ) -> BTreeMap<String, String>
    where
        F: FnMut(&BTreeMap<String, String>) -> bool,
    {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let result = app_chat_read(socket_path, surface_id);
            if predicate(&result) {
                return result;
            }
            assert!(
                Instant::now() < deadline,
                "chat state did not settle: {result:?}"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
    }

    #[cfg(any())]
    #[test]
    fn app_chat_surface_streams_stops_and_restores_over_a_real_socket() {
        let root =
            std::env::temp_dir().join(format!("sirio-main-chat-door-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let worktree_path = root.join("worktree");
        std::fs::create_dir_all(&worktree_path).expect("create chat worktree");
        let database_path = root.join("chat.sqlite");
        let socket_path = root.join("chat.sock");
        let worktree_id = "project-chat-wt-0";
        let surface_id = "project-chat-wt-0-tab-0";

        let database = AppDatabase::open(&database_path).expect("open chat database");
        database
            .save_project(&sirio_persistence::ProjectRecord::new(
                "project-chat",
                "fixture",
                worktree_path.to_string_lossy(),
            ))
            .expect("save chat project");
        database
            .save_worktree(&sirio_persistence::WorktreeRecord::new(
                worktree_id,
                "project-chat",
                "main",
                worktree_path.to_string_lossy(),
            ))
            .expect("save chat worktree");
        database
            .save_tab(&TabRecord::new(surface_id, worktree_id, "Chat", "chat"))
            .expect("save chat tab");
        drop(database);

        let catalog = ProjectCatalog::from_projects(vec![session::CatalogProject {
            id: "project-chat".into(),
            name: "fixture".into(),
            root_path: worktree_path.clone(),
            is_git: false,
            worktrees: vec![session::CatalogWorktree {
                branch: "main".into(),
                path: worktree_path.clone(),
                is_primary: true,
            }],
        }]);
        let state = Arc::new(Mutex::new(ControlState::from_catalog(
            &catalog,
            &worktree_path,
        )));
        let fixture = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../sirio_acp/tests/fixtures/acp_fixture.py");
        let normal_command = AgentCommand::new("python3")
            .arg(fixture.to_string_lossy().into_owned())
            .arg("normal");
        let normal_handler = Arc::new(AppControlHandler::new_with_chat_config(
            state.clone(),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(socket_path.clone()),
            database_path.clone(),
            normal_command,
        ));
        let server = ControlServer::new(socket_path.clone(), normal_handler.clone());
        server.start().expect("start chat control server");

        let round_trip = |request: ControlRequest| {
            sirio_control::round_trip(&socket_path, &request, Duration::from_secs(5))
                .expect("chat control round trip")
        };
        let opened = round_trip(sirio_control::protocol::request::chat_open(Some(
            worktree_id,
        )));
        assert!(opened.ok, "chat open failed: {opened:?}");
        assert_eq!(
            opened
                .result
                .as_ref()
                .and_then(|result| result.get("status")),
            Some(&"idle".to_string())
        );

        let composed = round_trip(sirio_control::protocol::request::chat_compose(
            surface_id,
            "queued after this turn",
        ));
        assert!(composed.ok, "chat compose failed: {composed:?}");
        assert_eq!(
            composed
                .result
                .as_ref()
                .and_then(|result| result.get("composerText")),
            Some(&"queued after this turn".to_string())
        );

        let sent = round_trip(sirio_control::protocol::request::chat_send(
            surface_id,
            "exercise the app chat door",
        ));
        assert!(sent.ok, "chat send failed: {sent:?}");
        assert_eq!(
            sent.result.as_ref().and_then(|result| result.get("status")),
            Some(&"streaming".to_string())
        );

        let pending = wait_for_app_chat_read(&socket_path, surface_id, |result| {
            sirio_control::protocol::rows::decode(result.get("transcript").expect("transcript"))
                .is_some_and(|rows| {
                    rows.iter().any(|row| {
                        row.get("kind").map(String::as_str) == Some("permission")
                            && row.get("status").map(String::as_str) == Some("pending")
                    })
                })
        });
        assert_eq!(pending.get("status").map(String::as_str), Some("streaming"));

        let permission = round_trip(sirio_control::protocol::request::chat_permission(
            surface_id, 1, "deny",
        ));
        assert!(permission.ok, "chat permission failed: {permission:?}");
        let completed = wait_for_app_chat_read(&socket_path, surface_id, |result| {
            result.get("status").map(String::as_str) == Some("completed")
        });
        let completed_transcript = completed.get("transcript").cloned().expect("transcript");

        server.stop();
        drop(server);
        drop(normal_handler);

        let cancel_command = AgentCommand::new("python3")
            .arg(fixture.to_string_lossy().into_owned())
            .arg("cancel");
        let restored_handler = Arc::new(AppControlHandler::new_with_chat_config(
            state,
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(socket_path.clone()),
            database_path.clone(),
            cancel_command,
        ));
        let restored_server = ControlServer::new(socket_path.clone(), restored_handler.clone());
        restored_server
            .start()
            .expect("restart chat control server");

        let restored = app_chat_read(&socket_path, surface_id);
        assert_eq!(
            restored.get("status").map(String::as_str),
            Some("completed")
        );
        assert_eq!(restored.get("transcript"), Some(&completed_transcript));

        let reopened = round_trip(sirio_control::protocol::request::chat_open(Some(
            worktree_id,
        )));
        assert!(reopened.ok, "reopen chat failed: {reopened:?}");
        round_trip(sirio_control::protocol::request::chat_send(
            surface_id,
            "stop this turn",
        ));
        wait_for_app_chat_read(&socket_path, surface_id, |result| {
            result.get("status").map(String::as_str) == Some("streaming")
                && sirio_control::protocol::rows::decode(
                    result.get("transcript").expect("transcript"),
                )
                .is_some_and(|rows| {
                    rows.iter().any(|row| {
                        row.get("kind").map(String::as_str) == Some("assistant")
                            && row.get("text").map(String::as_str) == Some("partial")
                    })
                })
        });
        let stopped_request = round_trip(sirio_control::protocol::request::chat_stop(surface_id));
        assert!(stopped_request.ok, "chat stop failed: {stopped_request:?}");
        let stopped = wait_for_app_chat_read(&socket_path, surface_id, |result| {
            result.get("status").map(String::as_str) == Some("stopped")
                && sirio_control::protocol::rows::decode(
                    result.get("transcript").expect("transcript"),
                )
                .is_some_and(|rows| {
                    rows.iter().any(|row| {
                        row.get("kind").map(String::as_str) == Some("turn")
                            && row.get("text").map(String::as_str) == Some("Cancelled")
                    })
                })
        });
        assert_eq!(stopped.get("status").map(String::as_str), Some("stopped"));

        restored_server.stop();
        drop(restored_server);
        drop(restored_handler);
        let relaunch_handler = Arc::new(AppControlHandler::new_with_chat_config(
            Arc::new(Mutex::new(ControlState::from_catalog(
                &catalog,
                &worktree_path,
            ))),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(PaneRegistry::new()),
            Arc::new(Mutex::new(Vec::new())),
            Arc::new(Mutex::new(BTreeMap::new())),
            None,
            ControlSocketInfo::new(socket_path.clone()),
            database_path,
            AgentCommand::new("python3"),
        ));
        let relaunch_server = ControlServer::new(socket_path.clone(), relaunch_handler.clone());
        relaunch_server.start().expect("start relaunch chat server");
        let relaunched = { app_chat_read(&socket_path, surface_id) };
        assert_eq!(
            relaunched.get("status").map(String::as_str),
            Some("stopped")
        );
        assert!(
            sirio_control::protocol::rows::decode(
                relaunched.get("transcript").expect("relaunch transcript")
            )
            .is_some_and(|rows| {
                rows.iter().any(|row| {
                    row.get("kind").map(String::as_str) == Some("turn")
                        && row.get("text").map(String::as_str) == Some("Cancelled")
                })
            })
        );
        relaunch_server.stop();
        drop(relaunch_server);
        drop(relaunch_handler);
        let _ = std::fs::remove_dir_all(root);
    }

